// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_SC: NistCatalogFamily = {"code":"SC","name":"System and Communications Protection","controls":[{"id":"SC-1","oscal_id":"sc-1","family":"SC","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> system and communications protection policy that:\n    <organization-defined parameter> system and communications protection policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the system and communications protection policy and the associated system and communications protection controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the system and communications protection policy and procedures; and\nc. Review and update the current system and communications protection:\n  Review and update the current system and communications protection:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"System and communications protection policy and procedures address the controls in the SC family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of system and communications protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to system and communications protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"sc-1_prm_1","label":"organization-defined personnel or roles"},{"id":"sc-01_odp.01","label":"personnel or roles"},{"id":"sc-01_odp.02","label":"personnel or roles"},{"id":"sc-01_odp.03","label":"","choices":["organization-level","mission/business-process-level","system-level"],"how_many":"one-or-more"},{"id":"sc-01_odp.04","label":"official"},{"id":"sc-01_odp.05","label":"frequency"},{"id":"sc-01_odp.06","label":"events"},{"id":"sc-01_odp.07","label":"frequency"},{"id":"sc-01_odp.08","label":"events"}],"objectives":[{"id":"sc-1_obj.a-1","label":"SC-01a.[01]","text":"a system and communications protection policy is developed and documented;"},{"id":"sc-1_obj.a-2","label":"SC-01a.[02]","text":"the system and communications protection policy is disseminated to {{ insert: param, sc-01_odp.01 }};"},{"id":"sc-1_obj.a-3","label":"SC-01a.[03]","text":"system and communications protection procedures to facilitate the implementation of the system and communications protection policy and associated system and communications protection controls are developed and documented;"},{"id":"sc-1_obj.a-4","label":"SC-01a.[04]","text":"the system and communications protection procedures are disseminated to {{ insert: param, sc-01_odp.02 }};"},{"id":"sc-1_obj.a.1.a-1","label":"SC-01a.01(a)[01]","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy addresses purpose;"},{"id":"sc-1_obj.a.1.a-2","label":"SC-01a.01(a)[02]","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy addresses scope;"},{"id":"sc-1_obj.a.1.a-3","label":"SC-01a.01(a)[03]","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy addresses roles;"},{"id":"sc-1_obj.a.1.a-4","label":"SC-01a.01(a)[04]","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy addresses responsibilities;"},{"id":"sc-1_obj.a.1.a-5","label":"SC-01a.01(a)[05]","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy addresses management commitment;"},{"id":"sc-1_obj.a.1.a-6","label":"SC-01a.01(a)[06]","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy addresses coordination among organizational entities;"},{"id":"sc-1_obj.a.1.a-7","label":"SC-01a.01(a)[07]","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy addresses compliance;"},{"id":"sc-1_obj.a.1.b","label":"SC-01a.01(b)","text":"the {{ insert: param, sc-01_odp.03 }} system and communications protection policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"sc-1_obj.b","label":"SC-01b.","text":"the {{ insert: param, sc-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the system and communications protection policy and procedures;"},{"id":"sc-1_obj.c.1-1","label":"SC-01c.01[01]","text":"the current system and communications protection policy is reviewed and updated {{ insert: param, sc-01_odp.05 }};"},{"id":"sc-1_obj.c.1-2","label":"SC-01c.01[02]","text":"the current system and communications protection policy is reviewed and updated following {{ insert: param, sc-01_odp.06 }};"},{"id":"sc-1_obj.c.2-1","label":"SC-01c.02[01]","text":"the current system and communications protection procedures are reviewed and updated {{ insert: param, sc-01_odp.07 }};"},{"id":"sc-1_obj.c.2-2","label":"SC-01c.02[02]","text":"the current system and communications protection procedures are reviewed and updated following {{ insert: param, sc-01_odp.08 }}."}],"methods":[{"method":"examine","label":"SC-01-Examine"},{"method":"interview","label":"SC-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-12"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SA-8","SI-12"]},{"id":"SC-2","oscal_id":"sc-2","family":"SC","title":"Separation of System and User Functionality","statement":"Separate user functionality, including user interface services, from system management functionality.","supplemental_guidance":"System management functionality includes functions that are necessary to administer databases, network components, workstations, or servers. These functions typically require privileged user access. The separation of user functions from system management functions is physical or logical. Organizations may separate system management functions from user functions by using different computers, instances of operating systems, central processing units, or network addresses; by employing virtualization techniques; or some combination of these or other methods. Separation of system management functions from user functions includes web administrative interfaces that employ separate authentication methods for users of any other system resources. Separation of system and user functions may include isolating administrative interfaces on different domains and with additional access controls. The separation of system and user functionality can be achieved by applying the systems security engineering design principles in [SA-8](#sa-8) , including [SA-8(1)](#sa-8.1), [SA-8(3)](#sa-8.3), [SA-8(4)](#sa-8.4), [SA-8(10)](#sa-8.10), [SA-8(12)](#sa-8.12), [SA-8(13)](#sa-8.13), [SA-8(14)](#sa-8.14) , and [SA-8(18)](#sa-8.18).","implementation_level":"system","methods":[{"method":"examine","label":"SC-02-Examine"},{"method":"interview","label":"SC-02-Interview"},{"method":"test","label":"SC-02-Test"}],"related_controls":["AC-6","SA-4","SA-8","SC-3","SC-7","SC-22","SC-32","SC-39"],"enhancements":[{"id":"SC-2(1)","oscal_id":"sc-2.1","family":"SC","title":"Interfaces for Non-privileged Users","statement":"Prevent the presentation of system management functionality at interfaces to non-privileged users.","supplemental_guidance":"Preventing the presentation of system management functionality at interfaces to non-privileged users ensures that system administration options, including administrator privileges, are not available to the general user population. Restricting user access also prohibits the use of the grey-out option commonly used to eliminate accessibility to such information. One potential solution is to withhold system administration options until users establish sessions with administrator privileges.","implementation_level":"system","methods":[{"method":"examine","label":"SC-02(01)-Examine"},{"method":"interview","label":"SC-02(01)-Interview"},{"method":"test","label":"SC-02(01)-Test"}],"related_controls":["AC-3"],"is_enhancement":true,"parent_id":"SC-2"},{"id":"SC-2(2)","oscal_id":"sc-2.2","family":"SC","title":"Disassociability","statement":"Store state information from applications and software separately.","supplemental_guidance":"If a system is compromised, storing applications and software separately from state information about users’ interactions with an application may better protect individuals’ privacy.","implementation_level":"system","methods":[{"method":"examine","label":"SC-02(02)-Examine"},{"method":"interview","label":"SC-02(02)-Interview"},{"method":"test","label":"SC-02(02)-Test"}],"is_enhancement":true,"parent_id":"SC-2"}]},{"id":"SC-3","oscal_id":"sc-3","family":"SC","title":"Security Function Isolation","statement":"Isolate security functions from nonsecurity functions.","supplemental_guidance":"Security functions are isolated from nonsecurity functions by means of an isolation boundary implemented within a system via partitions and domains. The isolation boundary controls access to and protects the integrity of the hardware, software, and firmware that perform system security functions. Systems implement code separation in many ways, such as through the provision of security kernels via processor rings or processor modes. For non-kernel code, security function isolation is often achieved through file system protections that protect the code on disk and address space protections that protect executing code. Systems can restrict access to security functions using access control mechanisms and by implementing least privilege capabilities. While the ideal is for all code within the defined security function isolation boundary to only contain security-relevant code, it is sometimes necessary to include nonsecurity functions as an exception. The isolation of security functions from nonsecurity functions can be achieved by applying the systems security engineering design principles in [SA-8](#sa-8) , including [SA-8(1)](#sa-8.1), [SA-8(3)](#sa-8.3), [SA-8(4)](#sa-8.4), [SA-8(10)](#sa-8.10), [SA-8(12)](#sa-8.12), [SA-8(13)](#sa-8.13), [SA-8(14)](#sa-8.14) , and [SA-8(18)](#sa-8.18).","implementation_level":"system","methods":[{"method":"examine","label":"SC-03-Examine"},{"method":"interview","label":"SC-03-Interview"},{"method":"test","label":"SC-03-Test"}],"related_controls":["AC-3","AC-6","AC-25","CM-2","CM-4","SA-4","SA-5","SA-8","SA-15","SA-17","SC-2","SC-7","SC-32","SC-39","SI-16"],"enhancements":[{"id":"SC-3(1)","oscal_id":"sc-3.1","family":"SC","title":"Hardware Separation","statement":"Employ hardware separation mechanisms to implement security function isolation.","supplemental_guidance":"Hardware separation mechanisms include hardware ring architectures that are implemented within microprocessors and hardware-enforced address segmentation used to support logically distinct storage objects with separate attributes (i.e., readable, writeable).","implementation_level":"system","methods":[{"method":"examine","label":"SC-03(01)-Examine"},{"method":"interview","label":"SC-03(01)-Interview"},{"method":"test","label":"SC-03(01)-Test"}],"is_enhancement":true,"parent_id":"SC-3"},{"id":"SC-3(2)","oscal_id":"sc-3.2","family":"SC","title":"Access and Flow Control Functions","statement":"Isolate security functions enforcing access and information flow control from nonsecurity functions and from other security functions.","supplemental_guidance":"Security function isolation occurs because of implementation. The functions can still be scanned and monitored. Security functions that are potentially isolated from access and flow control enforcement functions include auditing, intrusion detection, and malicious code protection functions.","implementation_level":"system","objectives":[{"id":"sc-3.2_obj-1","label":"SC-03(02)[01]","text":"security functions enforcing access control are isolated from non-security functions;"},{"id":"sc-3.2_obj-2","label":"SC-03(02)[02]","text":"security functions enforcing access control are isolated from other security functions;"},{"id":"sc-3.2_obj-3","label":"SC-03(02)[03]","text":"security functions enforcing information flow control are isolated from non-security functions;"},{"id":"sc-3.2_obj-4","label":"SC-03(02)[04]","text":"security functions enforcing information flow control are isolated from other security functions."}],"methods":[{"method":"examine","label":"SC-03(02)-Examine"},{"method":"interview","label":"SC-03(02)-Interview"},{"method":"test","label":"SC-03(02)-Test"}],"is_enhancement":true,"parent_id":"SC-3"},{"id":"SC-3(3)","oscal_id":"sc-3.3","family":"SC","title":"Minimize Nonsecurity Functionality","statement":"Minimize the number of nonsecurity functions included within the isolation boundary containing security functions.","supplemental_guidance":"Where it is not feasible to achieve strict isolation of nonsecurity functions from security functions, it is necessary to take actions to minimize nonsecurity-relevant functions within the security function boundary. Nonsecurity functions contained within the isolation boundary are considered security-relevant because errors or malicious code in the software can directly impact the security functions of systems. The fundamental design objective is that the specific portions of systems that provide information security are of minimal size and complexity. Minimizing the number of nonsecurity functions in the security-relevant system components allows designers and implementers to focus only on those functions which are necessary to provide the desired security capability (typically access enforcement). By minimizing the nonsecurity functions within the isolation boundaries, the amount of code that is trusted to enforce security policies is significantly reduced, thus contributing to understandability.","implementation_level":"organization","methods":[{"method":"examine","label":"SC-03(03)-Examine"},{"method":"interview","label":"SC-03(03)-Interview"},{"method":"test","label":"SC-03(03)-Test"}],"is_enhancement":true,"parent_id":"SC-3"},{"id":"SC-3(4)","oscal_id":"sc-3.4","family":"SC","title":"Module Coupling and Cohesiveness","statement":"Implement security functions as largely independent modules that maximize internal cohesiveness within modules and minimize coupling between modules.","supplemental_guidance":"The reduction of inter-module interactions helps to constrain security functions and manage complexity. The concepts of coupling and cohesion are important with respect to modularity in software design. Coupling refers to the dependencies that one module has on other modules. Cohesion refers to the relationship between functions within a module. Best practices in software engineering and systems security engineering rely on layering, minimization, and modular decomposition to reduce and manage complexity. This produces software modules that are highly cohesive and loosely coupled.","implementation_level":"organization","objectives":[{"id":"sc-3.4_obj-1","label":"SC-03(04)[01]","text":"security functions are implemented as largely independent modules that maximize internal cohesiveness within modules;"},{"id":"sc-3.4_obj-2","label":"SC-03(04)[02]","text":"security functions are implemented as largely independent modules that minimize coupling between modules."}],"methods":[{"method":"examine","label":"SC-03(04)-Examine"},{"method":"interview","label":"SC-03(04)-Interview"},{"method":"test","label":"SC-03(04)-Test"}],"is_enhancement":true,"parent_id":"SC-3"},{"id":"SC-3(5)","oscal_id":"sc-3.5","family":"SC","title":"Layered Structures","statement":"Implement security functions as a layered structure minimizing interactions between layers of the design and avoiding any dependence by lower layers on the functionality or correctness of higher layers.","supplemental_guidance":"The implementation of layered structures with minimized interactions among security functions and non-looping layers (i.e., lower-layer functions do not depend on higher-layer functions) enables the isolation of security functions and the management of complexity.","implementation_level":"organization","methods":[{"method":"examine","label":"SC-03(05)-Examine"},{"method":"interview","label":"SC-03(05)-Interview"},{"method":"test","label":"SC-03(05)-Test"}],"is_enhancement":true,"parent_id":"SC-3"}]},{"id":"SC-4","oscal_id":"sc-4","family":"SC","title":"Information in Shared System Resources","statement":"Prevent unauthorized and unintended information transfer via shared system resources.","supplemental_guidance":"Preventing unauthorized and unintended information transfer via shared system resources stops information produced by the actions of prior users or roles (or the actions of processes acting on behalf of prior users or roles) from being available to current users or roles (or current processes acting on behalf of current users or roles) that obtain access to shared system resources after those resources have been released back to the system. Information in shared system resources also applies to encrypted representations of information. In other contexts, control of information in shared system resources is referred to as object reuse and residual information protection. Information in shared system resources does not address information remanence, which refers to the residual representation of data that has been nominally deleted; covert channels (including storage and timing channels), where shared system resources are manipulated to violate information flow restrictions; or components within systems for which there are only single users or roles.","implementation_level":"system","objectives":[{"id":"sc-4_obj-1","label":"SC-04[01]","text":"unauthorized information transfer via shared system resources is prevented;"},{"id":"sc-4_obj-2","label":"SC-04[02]","text":"unintended information transfer via shared system resources is prevented."}],"methods":[{"method":"examine","label":"SC-04-Examine"},{"method":"interview","label":"SC-04-Interview"},{"method":"test","label":"SC-04-Test"}],"related_controls":["AC-3","AC-4","SA-8"],"enhancements":[{"id":"SC-4(1)","oscal_id":"sc-4.1","family":"SC","title":"Security Levels","statement":"","is_enhancement":true,"parent_id":"SC-4"},{"id":"SC-4(2)","oscal_id":"sc-4.2","family":"SC","title":"Multilevel or Periods Processing","statement":"Prevent unauthorized information transfer via shared resources in accordance with <procedures> when system processing explicitly switches between different information classification levels or security categories.","supplemental_guidance":"Changes in processing levels can occur during multilevel or periods processing with information at different classification levels or security categories. It can also occur during serial reuse of hardware components at different classification levels. Organization-defined procedures can include approved sanitization processes for electronically stored information.","implementation_level":"system","parameters":[{"id":"sc-04.02_odp","label":"procedures"}],"methods":[{"method":"examine","label":"SC-04(02)-Examine"},{"method":"interview","label":"SC-04(02)-Interview"},{"method":"test","label":"SC-04(02)-Test"}],"is_enhancement":true,"parent_id":"SC-4"}]},{"id":"SC-5","oscal_id":"sc-5","family":"SC","title":"Denial-of-service Protection","statement":"a. <organization-defined parameter> the effects of the following types of denial-of-service events: <types of denial-of-service events> ; and\nb. Employ the following controls to achieve the denial-of-service objective: <controls by type of denial-of-service event>.","supplemental_guidance":"Denial-of-service events may occur due to a variety of internal and external causes, such as an attack by an adversary or a lack of planning to support organizational needs with respect to capacity and bandwidth. Such attacks can occur across a wide range of network protocols (e.g., IPv4, IPv6). A variety of technologies are available to limit or eliminate the origination and effects of denial-of-service events. For example, boundary protection devices can filter certain types of packets to protect system components on internal networks from being directly affected by or the source of denial-of-service attacks. Employing increased network capacity and bandwidth combined with service redundancy also reduces the susceptibility to denial-of-service events.","implementation_level":"system","parameters":[{"id":"sc-05_odp.01","label":"types of denial-of-service events"},{"id":"sc-05_odp.02","label":"","choices":["protect against","limit"]},{"id":"sc-05_odp.03","label":"controls by type of denial-of-service event"}],"objectives":[{"id":"sc-5_obj.a","label":"SC-05a.","text":"the effects of {{ insert: param, sc-05_odp.01 }} are {{ insert: param, sc-05_odp.02 }};"},{"id":"sc-5_obj.b","label":"SC-05b.","text":"{{ insert: param, sc-05_odp.03 }} are employed to achieve the denial-of-service protection objective."}],"methods":[{"method":"examine","label":"SC-05-Examine"},{"method":"interview","label":"SC-05-Interview"},{"method":"test","label":"SC-05-Test"}],"references":[{"title":"SP 800-189"}],"related_controls":["CP-2","IR-4","SC-6","SC-7","SC-40"],"enhancements":[{"id":"SC-5(1)","oscal_id":"sc-5.1","family":"SC","title":"Restrict Ability to Attack Other Systems","statement":"Restrict the ability of individuals to launch the following denial-of-service attacks against other systems: <denial-of-service attacks>.","supplemental_guidance":"Restricting the ability of individuals to launch denial-of-service attacks requires the mechanisms commonly used for such attacks to be unavailable. Individuals of concern include hostile insiders or external adversaries who have breached or compromised the system and are using it to launch a denial-of-service attack. Organizations can restrict the ability of individuals to connect and transmit arbitrary information on the transport medium (i.e., wired networks, wireless networks, spoofed Internet protocol packets). Organizations can also limit the ability of individuals to use excessive system resources. Protection against individuals having the ability to launch denial-of-service attacks may be implemented on specific systems or boundary devices that prohibit egress to potential target systems.","implementation_level":"system","parameters":[{"id":"sc-05.01_odp","label":"denial-of-service attacks"}],"methods":[{"method":"examine","label":"SC-05(01)-Examine"},{"method":"interview","label":"SC-05(01)-Interview"},{"method":"test","label":"SC-05(01)-Test"}],"is_enhancement":true,"parent_id":"SC-5"},{"id":"SC-5(2)","oscal_id":"sc-5.2","family":"SC","title":"Capacity, Bandwidth, and Redundancy","statement":"Manage capacity, bandwidth, or other redundancy to limit the effects of information flooding denial-of-service attacks.","supplemental_guidance":"Managing capacity ensures that sufficient capacity is available to counter flooding attacks. Managing capacity includes establishing selected usage priorities, quotas, partitioning, or load balancing.","implementation_level":"system","methods":[{"method":"examine","label":"SC-05(02)-Examine"},{"method":"interview","label":"SC-05(02)-Interview"},{"method":"test","label":"SC-05(02)-Test"}],"is_enhancement":true,"parent_id":"SC-5"},{"id":"SC-5(3)","oscal_id":"sc-5.3","family":"SC","title":"Detection and Monitoring","statement":"(a) Employ the following monitoring tools to detect indicators of denial-of-service attacks against, or launched from, the system: <monitoring tools> ; and\n(b) Monitor the following system resources to determine if sufficient resources exist to prevent effective denial-of-service attacks: <system resources>.","supplemental_guidance":"Organizations consider the utilization and capacity of system resources when managing risk associated with a denial of service due to malicious attacks. Denial-of-service attacks can originate from external or internal sources. System resources that are sensitive to denial of service include physical disk storage, memory, and CPU cycles. Techniques used to prevent denial-of-service attacks related to storage utilization and capacity include instituting disk quotas, configuring systems to automatically alert administrators when specific storage capacity thresholds are reached, using file compression technologies to maximize available storage space, and imposing separate partitions for system and user data.","implementation_level":"system","parameters":[{"id":"sc-05.03_odp.01","label":"monitoring tools"},{"id":"sc-05.03_odp.02","label":"system resources"}],"objectives":[{"id":"sc-5.3_obj.a","label":"SC-05(03)(a)","text":"{{ insert: param, sc-05.03_odp.01 }} are employed to detect indicators of denial-of-service attacks against or launched from the system;"},{"id":"sc-5.3_obj.b","label":"SC-05(03)(b)","text":"{{ insert: param, sc-05.03_odp.02 }} are monitored to determine if sufficient resources exist to prevent effective denial-of-service attacks."}],"methods":[{"method":"examine","label":"SC-05(03)-Examine"},{"method":"interview","label":"SC-05(03)-Interview"},{"method":"test","label":"SC-05(03)-Test"}],"related_controls":["CA-7","SI-4"],"is_enhancement":true,"parent_id":"SC-5"}]},{"id":"SC-6","oscal_id":"sc-6","family":"SC","title":"Resource Availability","statement":"Protect the availability of resources by allocating <resources> by <organization-defined parameter>.","supplemental_guidance":"Priority protection prevents lower-priority processes from delaying or interfering with the system that services higher-priority processes. Quotas prevent users or processes from obtaining more than predetermined amounts of resources.","implementation_level":"system","parameters":[{"id":"sc-06_odp.01","label":"resources"},{"id":"sc-06_odp.02","label":"","choices":["priority","quota","{{ insert: param, sc-06_odp.03 }} "],"how_many":"one-or-more"},{"id":"sc-06_odp.03","label":"controls"}],"methods":[{"method":"examine","label":"SC-06-Examine"},{"method":"interview","label":"SC-06-Interview"},{"method":"test","label":"SC-06-Test"}],"references":[{"title":"OMB M-08-05"},{"title":"DHS TIC"}],"related_controls":["SC-5"]},{"id":"SC-7","oscal_id":"sc-7","family":"SC","title":"Boundary Protection","statement":"a. Monitor and control communications at the external managed interfaces to the system and at key internal managed interfaces within the system;\nb. Implement subnetworks for publicly accessible system components that are <organization-defined parameter> separated from internal organizational networks; and\nc. Connect to external networks or systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture.","supplemental_guidance":"Managed interfaces include gateways, routers, firewalls, guards, network-based malicious code analysis, virtualization systems, or encrypted tunnels implemented within a security architecture. Subnetworks that are physically or logically separated from internal networks are referred to as demilitarized zones or DMZs. Restricting or prohibiting interfaces within organizational systems includes restricting external web traffic to designated web servers within managed interfaces, prohibiting external traffic that appears to be spoofing internal addresses, and prohibiting internal traffic that appears to be spoofing external addresses. [SP 800-189](#f5edfe51-d1f2-422e-9b27-5d0e90b49c72) provides additional information on source address validation techniques to prevent ingress and egress of traffic with spoofed addresses. Commercial telecommunications services are provided by network components and consolidated management systems shared by customers. These services may also include third party-provided access lines and other service elements. Such services may represent sources of increased risk despite contract security provisions. Boundary protection may be implemented as a common control for all or part of an organizational network such that the boundary to be protected is greater than a system-specific boundary (i.e., an authorization boundary).","implementation_level":"system","parameters":[{"id":"sc-07_odp","label":"","choices":["physically","logically"]}],"objectives":[{"id":"sc-7_obj.a-1","label":"SC-07a.[01]","text":"communications at external managed interfaces to the system are monitored;"},{"id":"sc-7_obj.a-2","label":"SC-07a.[02]","text":"communications at external managed interfaces to the system are controlled;"},{"id":"sc-7_obj.a-3","label":"SC-07a.[03]","text":"communications at key internal managed interfaces within the system are monitored;"},{"id":"sc-7_obj.a-4","label":"SC-07a.[04]","text":"communications at key internal managed interfaces within the system are controlled;"},{"id":"sc-7_obj.b","label":"SC-07b.","text":"subnetworks for publicly accessible system components are {{ insert: param, sc-07_odp }} separated from internal organizational networks;"},{"id":"sc-7_obj.c","label":"SC-07c.","text":"external networks or systems are only connected to through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture."}],"methods":[{"method":"examine","label":"SC-07-Examine"},{"method":"interview","label":"SC-07-Interview"},{"method":"test","label":"SC-07-Test"}],"references":[{"title":"OMB A-130"},{"title":"FIPS 199"},{"title":"SP 800-37"},{"title":"SP 800-41"},{"title":"SP 800-77"},{"title":"SP 800-189"}],"related_controls":["AC-4","AC-17","AC-18","AC-19","AC-20","AU-13","CA-3","CM-2","CM-4","CM-7","CM-10","CP-8","CP-10","IR-4","MA-4","PE-3","PL-8","PM-12","SA-8","SA-17","SC-5","SC-26","SC-32","SC-35","SC-43"],"enhancements":[{"id":"SC-7(1)","oscal_id":"sc-7.1","family":"SC","title":"Physically Separated Subnetworks","statement":"","is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(2)","oscal_id":"sc-7.2","family":"SC","title":"Public Access","statement":"","is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(3)","oscal_id":"sc-7.3","family":"SC","title":"Access Points","statement":"Limit the number of external network connections to the system.","supplemental_guidance":"Limiting the number of external network connections facilitates monitoring of inbound and outbound communications traffic. The Trusted Internet Connection [DHS TIC](#4f42ee6e-86cc-403b-a51f-76c2b4f81b54) initiative is an example of a federal guideline that requires limits on the number of external network connections. Limiting the number of external network connections to the system is important during transition periods from older to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols). Such transitions may require implementing the older and newer technologies simultaneously during the transition period and thus increase the number of access points to the system.","implementation_level":"system","methods":[{"method":"examine","label":"SC-07(03)-Examine"},{"method":"interview","label":"SC-07(03)-Interview"},{"method":"test","label":"SC-07(03)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(4)","oscal_id":"sc-7.4","family":"SC","title":"External Telecommunications Services","statement":"(a) Implement a managed interface for each external telecommunication service;\n(b) Establish a traffic flow policy for each managed interface;\n(c) Protect the confidentiality and integrity of the information being transmitted across each interface;\n(d) Document each exception to the traffic flow policy with a supporting mission or business need and duration of that need;\n(e) Review exceptions to the traffic flow policy <frequency> and remove exceptions that are no longer supported by an explicit mission or business need;\n(f) Prevent unauthorized exchange of control plane traffic with external networks;\n(g) Publish information to enable remote networks to detect unauthorized control plane traffic from internal networks; and\n(h) Filter unauthorized control plane traffic from external networks.","supplemental_guidance":"External telecommunications services can provide data and/or voice communications services. Examples of control plane traffic include Border Gateway Protocol (BGP) routing, Domain Name System (DNS), and management protocols. See [SP 800-189](#f5edfe51-d1f2-422e-9b27-5d0e90b49c72) for additional information on the use of the resource public key infrastructure (RPKI) to protect BGP routes and detect unauthorized BGP announcements.","implementation_level":"organization","parameters":[{"id":"sc-07.04_odp","label":"frequency"}],"objectives":[{"id":"sc-7.4_obj.a","label":"SC-07(04)(a)","text":"a managed interface is implemented for each external telecommunication service;"},{"id":"sc-7.4_obj.b","label":"SC-07(04)(b)","text":"a traffic flow policy is established for each managed interface;"},{"id":"sc-7.4_obj.c-1","label":"SC-07(04)(c)[01]","text":"the confidentiality of the information being transmitted across each interface is protected;"},{"id":"sc-7.4_obj.c-2","label":"SC-07(04)(c)[02]","text":"the integrity of the information being transmitted across each interface is protected;"},{"id":"sc-7.4_obj.d","label":"SC-07(04)(d)","text":"each exception to the traffic flow policy is documented with a supporting mission or business need and duration of that need;"},{"id":"sc-7.4_obj.e-1","label":"SC-07(04)(e)[01]","text":"exceptions to the traffic flow policy are reviewed {{ insert: param, sc-07.04_odp }};"},{"id":"sc-7.4_obj.e-2","label":"SC-07(04)(e)[02]","text":"exceptions to the traffic flow policy that are no longer supported by an explicit mission or business need are removed;"},{"id":"sc-7.4_obj.f","label":"SC-07(04)(f)","text":"unauthorized exchanges of control plan traffic with external networks are prevented;"},{"id":"sc-7.4_obj.g","label":"SC-07(04)(g)","text":"information is published to enable remote networks to detect unauthorized control plane traffic from internal networks;"},{"id":"sc-7.4_obj.h","label":"SC-07(04)(h)","text":"unauthorized control plane traffic is filtered from external networks."}],"methods":[{"method":"examine","label":"SC-07(04)-Examine"},{"method":"interview","label":"SC-07(04)-Interview"},{"method":"test","label":"SC-07(04)-Test"}],"related_controls":["AC-3","SC-8","SC-20","SC-21","SC-22"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(5)","oscal_id":"sc-7.5","family":"SC","title":"Deny by Default — Allow by Exception","statement":"Deny network communications traffic by default and allow network communications traffic by exception <organization-defined parameter>.","supplemental_guidance":"Denying by default and allowing by exception applies to inbound and outbound network communications traffic. A deny-all, permit-by-exception network communications traffic policy ensures that only those system connections that are essential and approved are allowed. Deny by default, allow by exception also applies to a system that is connected to an external system.","implementation_level":"system","parameters":[{"id":"sc-07.05_odp.01","label":"","choices":["at managed interfaces","for {{ insert: param, sc-07.05_odp.02 }} "],"how_many":"one-or-more"},{"id":"sc-07.05_odp.02","label":"systems"}],"objectives":[{"id":"sc-7.5_obj-1","label":"SC-07(05)[01]","text":"network communications traffic is denied by default {{ insert: param, sc-07.05_odp.01 }};"},{"id":"sc-7.5_obj-2","label":"SC-07(05)[02]","text":"network communications traffic is allowed by exception {{ insert: param, sc-07.05_odp.01 }}."}],"methods":[{"method":"examine","label":"SC-07(05)-Examine"},{"method":"interview","label":"SC-07(05)-Interview"},{"method":"test","label":"SC-07(05)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(6)","oscal_id":"sc-7.6","family":"SC","title":"Response to Recognized Failures","statement":"","is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(7)","oscal_id":"sc-7.7","family":"SC","title":"Split Tunneling for Remote Devices","statement":"Prevent split tunneling for remote devices connecting to organizational systems unless the split tunnel is securely provisioned using <safeguards>.","supplemental_guidance":"Split tunneling is the process of allowing a remote user or device to establish a non-remote connection with a system and simultaneously communicate via some other connection to a resource in an external network. This method of network access enables a user to access remote devices and simultaneously, access uncontrolled networks. Split tunneling might be desirable by remote users to communicate with local system resources, such as printers or file servers. However, split tunneling can facilitate unauthorized external connections, making the system vulnerable to attack and to exfiltration of organizational information. Split tunneling can be prevented by disabling configuration settings that allow such capability in remote devices and by preventing those configuration settings from being configurable by users. Prevention can also be achieved by the detection of split tunneling (or of configuration settings that allow split tunneling) in the remote device, and by prohibiting the connection if the remote device is using split tunneling. A virtual private network (VPN) can be used to securely provision a split tunnel. A securely provisioned VPN includes locking connectivity to exclusive, managed, and named environments, or to a specific set of pre-approved addresses, without user control.","implementation_level":"system","parameters":[{"id":"sc-07.07_odp","label":"safeguards"}],"methods":[{"method":"examine","label":"SC-07(07)-Examine"},{"method":"interview","label":"SC-07(07)-Interview"},{"method":"test","label":"SC-07(07)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(8)","oscal_id":"sc-7.8","family":"SC","title":"Route Traffic to Authenticated Proxy Servers","statement":"Route <internal communications traffic> to <external networks> through authenticated proxy servers at managed interfaces.","supplemental_guidance":"External networks are networks outside of organizational control. A proxy server is a server (i.e., system or application) that acts as an intermediary for clients requesting system resources from non-organizational or other organizational servers. System resources that may be requested include files, connections, web pages, or services. Client requests established through a connection to a proxy server are assessed to manage complexity and provide additional protection by limiting direct connectivity. Web content filtering devices are one of the most common proxy servers that provide access to the Internet. Proxy servers can support the logging of Transmission Control Protocol sessions and the blocking of specific Uniform Resource Locators, Internet Protocol addresses, and domain names. Web proxies can be configured with organization-defined lists of authorized and unauthorized websites. Note that proxy servers may inhibit the use of virtual private networks (VPNs) and create the potential for \"man-in-the-middle\" attacks (depending on the implementation).","implementation_level":"system","parameters":[{"id":"sc-07.08_odp.01","label":"internal communications traffic"},{"id":"sc-07.08_odp.02","label":"external networks"}],"methods":[{"method":"examine","label":"SC-07(08)-Examine"},{"method":"interview","label":"SC-07(08)-Interview"},{"method":"test","label":"SC-07(08)-Test"}],"related_controls":["AC-3"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(9)","oscal_id":"sc-7.9","family":"SC","title":"Restrict Threatening Outgoing Communications Traffic","statement":"(a) Detect and deny outgoing communications traffic posing a threat to external systems; and\n(b) Audit the identity of internal users associated with denied communications.","supplemental_guidance":"Detecting outgoing communications traffic from internal actions that may pose threats to external systems is known as extrusion detection. Extrusion detection is carried out within the system at managed interfaces. Extrusion detection includes the analysis of incoming and outgoing communications traffic while searching for indications of internal threats to the security of external systems. Internal threats to external systems include traffic indicative of denial-of-service attacks, traffic with spoofed source addresses, and traffic that contains malicious code. Organizations have criteria to determine, update, and manage identified threats related to extrusion detection.","implementation_level":"system","objectives":[{"id":"sc-7.9_obj.a-1","label":"SC-07(09)(a)[01]","text":"outgoing communications traffic posing a threat to external systems is detected;"},{"id":"sc-7.9_obj.a-2","label":"SC-07(09)(a)[02]","text":"outgoing communications traffic posing a threat to external systems is denied;"},{"id":"sc-7.9_obj.b","label":"SC-07(09)(b)","text":"the identity of internal users associated with denied communications is audited."}],"methods":[{"method":"examine","label":"SC-07(09)-Examine"},{"method":"interview","label":"SC-07(09)-Interview"},{"method":"test","label":"SC-07(09)-Test"}],"related_controls":["AU-2","AU-6","SC-5","SC-38","SC-44","SI-3","SI-4"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(10)","oscal_id":"sc-7.10","family":"SC","title":"Prevent Exfiltration","statement":"(a) Prevent the exfiltration of information; and\n(b) Conduct exfiltration tests <frequency>.","supplemental_guidance":"Prevention of exfiltration applies to both the intentional and unintentional exfiltration of information. Techniques used to prevent the exfiltration of information from systems may be implemented at internal endpoints, external boundaries, and across managed interfaces and include adherence to protocol formats, monitoring for beaconing activity from systems, disconnecting external network interfaces except when explicitly needed, employing traffic profile analysis to detect deviations from the volume and types of traffic expected, call backs to command and control centers, conducting penetration testing, monitoring for steganography, disassembling and reassembling packet headers, and using data loss and data leakage prevention tools. Devices that enforce strict adherence to protocol formats include deep packet inspection firewalls and Extensible Markup Language (XML) gateways. The devices verify adherence to protocol formats and specifications at the application layer and identify vulnerabilities that cannot be detected by devices that operate at the network or transport layers. The prevention of exfiltration is similar to data loss prevention or data leakage prevention and is closely associated with cross-domain solutions and system guards that enforce information flow requirements.","implementation_level":"system","parameters":[{"id":"sc-07.10_odp","label":"frequency"}],"objectives":[{"id":"sc-7.10_obj.a","label":"SC-07(10)(a)","text":"the exfiltration of information is prevented;"},{"id":"sc-7.10_obj.b","label":"SC-07(10)(b)","text":"exfiltration tests are conducted {{ insert: param, sc-07.10_odp }}."}],"methods":[{"method":"examine","label":"SC-07(10)-Examine"},{"method":"interview","label":"SC-07(10)-Interview"},{"method":"test","label":"SC-07(10)-Test"}],"related_controls":["AC-2","CA-8","SI-3"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(11)","oscal_id":"sc-7.11","family":"SC","title":"Restrict Incoming Communications Traffic","statement":"Only allow incoming communications from <authorized sources> to be routed to <authorized destinations>.","supplemental_guidance":"General source address validation techniques are applied to restrict the use of illegal and unallocated source addresses as well as source addresses that should only be used within the system. The restriction of incoming communications traffic provides determinations that source and destination address pairs represent authorized or allowed communications. Determinations can be based on several factors, including the presence of such address pairs in the lists of authorized or allowed communications, the absence of such address pairs in lists of unauthorized or disallowed pairs, or meeting more general rules for authorized or allowed source and destination pairs. Strong authentication of network addresses is not possible without the use of explicit security protocols, and thus, addresses can often be spoofed. Further, identity-based incoming traffic restriction methods can be employed, including router access control lists and firewall rules.","implementation_level":"system","parameters":[{"id":"sc-07.11_odp.01","label":"authorized sources"},{"id":"sc-07.11_odp.02","label":"authorized destinations"}],"methods":[{"method":"examine","label":"SC-07(11)-Examine"},{"method":"interview","label":"SC-07(11)-Interview"},{"method":"test","label":"SC-07(11)-Test"}],"related_controls":["AC-3"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(12)","oscal_id":"sc-7.12","family":"SC","title":"Host-based Protection","statement":"Implement <host-based boundary protection mechanisms> at <system components>.","supplemental_guidance":"Host-based boundary protection mechanisms include host-based firewalls. System components that employ host-based boundary protection mechanisms include servers, workstations, notebook computers, and mobile devices.","implementation_level":"system","parameters":[{"id":"sc-07.12_odp.01","label":"host-based boundary protection mechanisms"},{"id":"sc-07.12_odp.02","label":"system components"}],"methods":[{"method":"examine","label":"SC-07(12)-Examine"},{"method":"interview","label":"SC-07(12)-Interview"},{"method":"test","label":"SC-07(12)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(13)","oscal_id":"sc-7.13","family":"SC","title":"Isolation of Security Tools, Mechanisms, and Support Components","statement":"Isolate <information security tools, mechanisms, and support components> from other internal system components by implementing physically separate subnetworks with managed interfaces to other components of the system.","supplemental_guidance":"Physically separate subnetworks with managed interfaces are useful in isolating computer network defenses from critical operational processing networks to prevent adversaries from discovering the analysis and forensics techniques employed by organizations.","implementation_level":"system","parameters":[{"id":"sc-07.13_odp","label":"information security tools, mechanisms, and support components"}],"methods":[{"method":"examine","label":"SC-07(13)-Examine"},{"method":"interview","label":"SC-07(13)-Interview"},{"method":"test","label":"SC-07(13)-Test"}],"related_controls":["SC-2","SC-3"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(14)","oscal_id":"sc-7.14","family":"SC","title":"Protect Against Unauthorized Physical Connections","statement":"Protect against unauthorized physical connections at <managed interfaces>.","supplemental_guidance":"Systems that operate at different security categories or classification levels may share common physical and environmental controls, since the systems may share space within the same facilities. In practice, it is possible that these separate systems may share common equipment rooms, wiring closets, and cable distribution paths. Protection against unauthorized physical connections can be achieved by using clearly identified and physically separated cable trays, connection frames, and patch panels for each side of managed interfaces with physical access controls that enforce limited authorized access to these items.","implementation_level":"system","parameters":[{"id":"sc-07.14_odp","label":"managed interfaces"}],"methods":[{"method":"examine","label":"SC-07(14)-Examine"},{"method":"interview","label":"SC-07(14)-Interview"},{"method":"test","label":"SC-07(14)-Test"}],"related_controls":["PE-4","PE-19"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(15)","oscal_id":"sc-7.15","family":"SC","title":"Networked Privileged Accesses","statement":"Route networked, privileged accesses through a dedicated, managed interface for purposes of access control and auditing.","supplemental_guidance":"Privileged access provides greater accessibility to system functions, including security functions. Adversaries attempt to gain privileged access to systems through remote access to cause adverse mission or business impacts, such as by exfiltrating information or bringing down a critical system capability. Routing networked, privileged access requests through a dedicated, managed interface further restricts privileged access for increased access control and auditing.","implementation_level":"system","objectives":[{"id":"sc-7.15_obj-1","label":"SC-07(15)[01]","text":"networked, privileged accesses are routed through a dedicated, managed interface for purposes of access control;"},{"id":"sc-7.15_obj-2","label":"SC-07(15)[02]","text":"networked, privileged accesses are routed through a dedicated, managed interface for purposes of auditing."}],"methods":[{"method":"examine","label":"SC-07(15)-Examine"},{"method":"interview","label":"SC-07(15)-Interview"},{"method":"test","label":"SC-07(15)-Test"}],"related_controls":["AC-2","AC-3","AU-2","SI-4"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(16)","oscal_id":"sc-7.16","family":"SC","title":"Prevent Discovery of System Components","statement":"Prevent the discovery of specific system components that represent a managed interface.","supplemental_guidance":"Preventing the discovery of system components representing a managed interface helps protect network addresses of those components from discovery through common tools and techniques used to identify devices on networks. Network addresses are not available for discovery and require prior knowledge for access. Preventing the discovery of components and devices can be accomplished by not publishing network addresses, using network address translation, or not entering the addresses in domain name systems. Another prevention technique is to periodically change network addresses.","implementation_level":"system","methods":[{"method":"examine","label":"SC-07(16)-Examine"},{"method":"interview","label":"SC-07(16)-Interview"},{"method":"test","label":"SC-07(16)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(17)","oscal_id":"sc-7.17","family":"SC","title":"Automated Enforcement of Protocol Formats","statement":"Enforce adherence to protocol formats.","supplemental_guidance":"System components that enforce protocol formats include deep packet inspection firewalls and XML gateways. The components verify adherence to protocol formats and specifications at the application layer and identify vulnerabilities that cannot be detected by devices operating at the network or transport layers.","implementation_level":"system","methods":[{"method":"examine","label":"SC-07(17)-Examine"},{"method":"interview","label":"SC-07(17)-Interview"},{"method":"test","label":"SC-07(17)-Test"}],"related_controls":["SC-4"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(18)","oscal_id":"sc-7.18","family":"SC","title":"Fail Secure","statement":"Prevent systems from entering unsecure states in the event of an operational failure of a boundary protection device.","supplemental_guidance":"Fail secure is a condition achieved by employing mechanisms to ensure that in the event of operational failures of boundary protection devices at managed interfaces, systems do not enter into unsecure states where intended security properties no longer hold. Managed interfaces include routers, firewalls, and application gateways that reside on protected subnetworks (commonly referred to as demilitarized zones). Failures of boundary protection devices cannot lead to or cause information external to the devices to enter the devices nor can failures permit unauthorized information releases.","implementation_level":"system","methods":[{"method":"examine","label":"SC-07(18)-Examine"},{"method":"interview","label":"SC-07(18)-Interview"},{"method":"test","label":"SC-07(18)-Test"}],"related_controls":["CP-2","CP-12","SC-24"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(19)","oscal_id":"sc-7.19","family":"SC","title":"Block Communication from Non-organizationally Configured Hosts","statement":"Block inbound and outbound communications traffic between <communication clients> that are independently configured by end users and external service providers.","supplemental_guidance":"Communication clients independently configured by end users and external service providers include instant messaging clients and video conferencing software and applications. Traffic blocking does not apply to communication clients that are configured by organizations to perform authorized functions.","implementation_level":"system","parameters":[{"id":"sc-07.19_odp","label":"communication clients"}],"objectives":[{"id":"sc-7.19_obj-1","label":"SC-07(19)[01]","text":"inbound communications traffic is blocked between {{ insert: param, sc-07.19_odp }} that are independently configured by end users and external service providers;"},{"id":"sc-7.19_obj-2","label":"SC-07(19)[02]","text":"outbound communications traffic is blocked between {{ insert: param, sc-07.19_odp }} that are independently configured by end users and external service providers."}],"methods":[{"method":"examine","label":"SC-07(19)-Examine"},{"method":"interview","label":"SC-07(19)-Interview"},{"method":"test","label":"SC-07(19)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(20)","oscal_id":"sc-7.20","family":"SC","title":"Dynamic Isolation and Segregation","statement":"Provide the capability to dynamically isolate <system components> from other system components.","supplemental_guidance":"The capability to dynamically isolate certain internal system components is useful when it is necessary to partition or separate system components of questionable origin from components that possess greater trustworthiness. Component isolation reduces the attack surface of organizational systems. Isolating selected system components can also limit the damage from successful attacks when such attacks occur.","implementation_level":"system","parameters":[{"id":"sc-07.20_odp","label":"system components"}],"methods":[{"method":"examine","label":"SC-07(20)-Examine"},{"method":"interview","label":"SC-07(20)-Interview"},{"method":"test","label":"SC-07(20)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(21)","oscal_id":"sc-7.21","family":"SC","title":"Isolation of System Components","statement":"Employ boundary protection mechanisms to isolate <system components> supporting <missions and/or business functions>.","supplemental_guidance":"Organizations can isolate system components that perform different mission or business functions. Such isolation limits unauthorized information flows among system components and provides the opportunity to deploy greater levels of protection for selected system components. Isolating system components with boundary protection mechanisms provides the capability for increased protection of individual system components and to more effectively control information flows between those components. Isolating system components provides enhanced protection that limits the potential harm from hostile cyber-attacks and errors. The degree of isolation varies depending upon the mechanisms chosen. Boundary protection mechanisms include routers, gateways, and firewalls that separate system components into physically separate networks or subnetworks; cross-domain devices that separate subnetworks; virtualization techniques; and the encryption of information flows among system components using distinct encryption keys.","implementation_level":"organization","parameters":[{"id":"sc-07.21_odp.01","label":"system components"},{"id":"sc-07.21_odp.02","label":"missions and/or business functions"}],"methods":[{"method":"examine","label":"SC-07(21)-Examine"},{"method":"interview","label":"SC-07(21)-Interview"},{"method":"test","label":"SC-07(21)-Test"}],"related_controls":["CA-9"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(22)","oscal_id":"sc-7.22","family":"SC","title":"Separate Subnets for Connecting to Different Security Domains","statement":"Implement separate network addresses to connect to systems in different security domains.","supplemental_guidance":"The decomposition of systems into subnetworks (i.e., subnets) helps to provide the appropriate level of protection for network connections to different security domains that contain information with different security categories or classification levels.","implementation_level":"system","methods":[{"method":"examine","label":"SC-07(22)-Examine"},{"method":"interview","label":"SC-07(22)-Interview"},{"method":"test","label":"SC-07(22)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(23)","oscal_id":"sc-7.23","family":"SC","title":"Disable Sender Feedback on Protocol Validation Failure","statement":"Disable feedback to senders on protocol format validation failure.","supplemental_guidance":"Disabling feedback to senders when there is a failure in protocol validation format prevents adversaries from obtaining information that would otherwise be unavailable.","implementation_level":"system","methods":[{"method":"examine","label":"SC-07(23)-Examine"},{"method":"interview","label":"SC-07(23)-Interview"},{"method":"test","label":"SC-07(23)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(24)","oscal_id":"sc-7.24","family":"SC","title":"Personally Identifiable Information","statement":"For systems that process personally identifiable information:\n(a) Apply the following processing rules to data elements of personally identifiable information: <processing rules>;\n(b) Monitor for permitted processing at the external interfaces to the system and at key internal boundaries within the system;\n(c) Document each processing exception; and\n(d) Review and remove exceptions that are no longer supported.","supplemental_guidance":"Managing the processing of personally identifiable information is an important aspect of protecting an individual’s privacy. Applying, monitoring for, and documenting exceptions to processing rules ensure that personally identifiable information is processed only in accordance with established privacy requirements.","implementation_level":"organization","parameters":[{"id":"sc-07.24_odp","label":"processing rules"}],"objectives":[{"id":"sc-7.24_obj.a","label":"SC-07(24)(a)","text":"{{ insert: param, sc-07.24_odp }} are applied to data elements of personally identifiable information on systems that process personally identifiable information;"},{"id":"sc-7.24_obj.b-1","label":"SC-07(24)(b)[01]","text":"permitted processing is monitored at the external interfaces to the systems that process personally identifiable information;"},{"id":"sc-7.24_obj.b-2","label":"SC-07(24)(b)[02]","text":"permitted processing is monitored at key internal boundaries within the systems that process personally identifiable information;"},{"id":"sc-7.24_obj.c","label":"SC-07(24)(c)","text":"each processing exception is documented for systems that process personally identifiable information;"},{"id":"sc-7.24_obj.d-1","label":"SC-07(24)(d)[01]","text":"exceptions for systems that process personally identifiable information are reviewed;"},{"id":"sc-7.24_obj.d-2","label":"SC-07(24)(d)[02]","text":"exceptions for systems that process personally identifiable information that are no longer supported are removed."}],"methods":[{"method":"examine","label":"SC-07(24)-Examine"},{"method":"interview","label":"SC-07(24)-Interview"},{"method":"test","label":"SC-07(24)-Test"}],"related_controls":["PT-2","SI-15"],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(25)","oscal_id":"sc-7.25","family":"SC","title":"Unclassified National Security System Connections","statement":"Prohibit the direct connection of <unclassified national security system> to an external network without the use of <boundary protection device>.","supplemental_guidance":"A direct connection is a dedicated physical or virtual connection between two or more systems. Organizations typically do not have complete control over external networks, including the Internet. Boundary protection devices (e.g., firewalls, gateways, and routers) mediate communications and information flows between unclassified national security systems and external networks.","implementation_level":"organization","parameters":[{"id":"sc-07.25_odp.01","label":"unclassified national security system"},{"id":"sc-07.25_odp.02","label":"boundary protection device"}],"methods":[{"method":"examine","label":"SC-07(25)-Examine"},{"method":"interview","label":"SC-07(25)-Interview"},{"method":"test","label":"SC-07(25)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(26)","oscal_id":"sc-7.26","family":"SC","title":"Classified National Security System Connections","statement":"Prohibit the direct connection of a classified national security system to an external network without the use of <boundary protection device>.","supplemental_guidance":"A direct connection is a dedicated physical or virtual connection between two or more systems. Organizations typically do not have complete control over external networks, including the Internet. Boundary protection devices (e.g., firewalls, gateways, and routers) mediate communications and information flows between classified national security systems and external networks. In addition, approved boundary protection devices (typically managed interface or cross-domain systems) provide information flow enforcement from systems to external networks.","implementation_level":"organization","parameters":[{"id":"sc-07.26_odp","label":"boundary protection device"}],"methods":[{"method":"examine","label":"SC-07(26)-Examine"},{"method":"interview","label":"SC-07(26)-Interview"},{"method":"test","label":"SC-07(26)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(27)","oscal_id":"sc-7.27","family":"SC","title":"Unclassified Non-national Security System Connections","statement":"Prohibit the direct connection of <unclassified, non-national security system> to an external network without the use of <boundary protection device>.","supplemental_guidance":"A direct connection is a dedicated physical or virtual connection between two or more systems. Organizations typically do not have complete control over external networks, including the Internet. Boundary protection devices (e.g., firewalls, gateways, and routers) mediate communications and information flows between unclassified non-national security systems and external networks.","implementation_level":"organization","parameters":[{"id":"sc-07.27_odp.01","label":"unclassified, non-national security system"},{"id":"sc-07.27_odp.02","label":"boundary protection device"}],"methods":[{"method":"examine","label":"SC-07(27)-Examine"},{"method":"interview","label":"SC-07(27)-Interview"},{"method":"test","label":"SC-07(27)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(28)","oscal_id":"sc-7.28","family":"SC","title":"Connections to Public Networks","statement":"Prohibit the direct connection of <system> to a public network.","supplemental_guidance":"A direct connection is a dedicated physical or virtual connection between two or more systems. A public network is a network accessible to the public, including the Internet and organizational extranets with public access.","implementation_level":"organization","parameters":[{"id":"sc-07.28_odp","label":"system"}],"methods":[{"method":"examine","label":"SC-07(28)-Examine"},{"method":"interview","label":"SC-07(28)-Interview"},{"method":"test","label":"SC-07(28)-Test"}],"is_enhancement":true,"parent_id":"SC-7"},{"id":"SC-7(29)","oscal_id":"sc-7.29","family":"SC","title":"Separate Subnets to Isolate Functions","statement":"Implement <organization-defined parameter> separate subnetworks to isolate the following critical system components and functions: <critical system components and functions>.","supplemental_guidance":"Separating critical system components and functions from other noncritical system components and functions through separate subnetworks may be necessary to reduce susceptibility to a catastrophic or debilitating breach or compromise that results in system failure. For example, physically separating the command and control function from the in-flight entertainment function through separate subnetworks in a commercial aircraft provides an increased level of assurance in the trustworthiness of critical system functions.","implementation_level":"system","parameters":[{"id":"sc-07.29_odp.01","label":"","choices":["physically","logically"]},{"id":"sc-07.29_odp.02","label":"critical system components and functions"}],"methods":[{"method":"examine","label":"SC-07(29)-Examine"},{"method":"interview","label":"SC-07(29)-Interview"},{"method":"test","label":"SC-07(29)-Test"}],"is_enhancement":true,"parent_id":"SC-7"}]},{"id":"SC-8","oscal_id":"sc-8","family":"SC","title":"Transmission Confidentiality and Integrity","statement":"Protect the <organization-defined parameter> of transmitted information.","supplemental_guidance":"Protecting the confidentiality and integrity of transmitted information applies to internal and external networks as well as any system components that can transmit information, including servers, notebook computers, desktop computers, mobile devices, printers, copiers, scanners, facsimile machines, and radios. Unprotected communication paths are exposed to the possibility of interception and modification. Protecting the confidentiality and integrity of information can be accomplished by physical or logical means. Physical protection can be achieved by using protected distribution systems. A protected distribution system is a wireline or fiber-optics telecommunications system that includes terminals and adequate electromagnetic, acoustical, electrical, and physical controls to permit its use for the unencrypted transmission of classified information. Logical protection can be achieved by employing encryption techniques.\n\nOrganizations that rely on commercial providers who offer transmission services as commodity services rather than as fully dedicated services may find it difficult to obtain the necessary assurances regarding the implementation of needed controls for transmission confidentiality and integrity. In such situations, organizations determine what types of confidentiality or integrity services are available in standard, commercial telecommunications service packages. If it is not feasible to obtain the necessary controls and assurances of control effectiveness through appropriate contracting vehicles, organizations can implement appropriate compensating controls.","implementation_level":"system","parameters":[{"id":"sc-08_odp","label":"","choices":["confidentiality","integrity"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"SC-08-Examine"},{"method":"interview","label":"SC-08-Interview"},{"method":"test","label":"SC-08-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 197"},{"title":"SP 800-52"},{"title":"SP 800-77"},{"title":"SP 800-81-2"},{"title":"SP 800-113"},{"title":"SP 800-177"},{"title":"IR 8023"}],"related_controls":["AC-17","AC-18","AU-10","IA-3","IA-8","IA-9","MA-4","PE-4","SA-4","SA-8","SC-7","SC-16","SC-20","SC-23","SC-28"],"enhancements":[{"id":"SC-8(1)","oscal_id":"sc-8.1","family":"SC","title":"Cryptographic Protection","statement":"Implement cryptographic mechanisms to <organization-defined parameter> during transmission.","supplemental_guidance":"Encryption protects information from unauthorized disclosure and modification during transmission. Cryptographic mechanisms that protect the confidentiality and integrity of information during transmission include TLS and IPSec. Cryptographic mechanisms used to protect information integrity include cryptographic hash functions that have applications in digital signatures, checksums, and message authentication codes.","implementation_level":"system","parameters":[{"id":"sc-08.01_odp","label":"","choices":["prevent unauthorized disclosure of information","detect changes to information"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"SC-08(01)-Examine"},{"method":"interview","label":"SC-08(01)-Interview"},{"method":"test","label":"SC-08(01)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-8"},{"id":"SC-8(2)","oscal_id":"sc-8.2","family":"SC","title":"Pre- and Post-transmission Handling","statement":"Maintain the <organization-defined parameter> of information during preparation for transmission and during reception.","supplemental_guidance":"Information can be unintentionally or maliciously disclosed or modified during preparation for transmission or during reception, including during aggregation, at protocol transformation points, and during packing and unpacking. Such unauthorized disclosures or modifications compromise the confidentiality or integrity of the information.","implementation_level":"system","parameters":[{"id":"sc-08.02_odp","label":"","choices":["confidentiality","integrity"],"how_many":"one-or-more"}],"objectives":[{"id":"sc-8.2_obj-1","label":"SC-08(02)[01]","text":"information {{ insert: param, sc-08.02_odp }} is/are maintained during preparation for transmission;"},{"id":"sc-8.2_obj-2","label":"SC-08(02)[02]","text":"information {{ insert: param, sc-08.02_odp }} is/are maintained during reception."}],"methods":[{"method":"examine","label":"SC-08(02)-Examine"},{"method":"interview","label":"SC-08(02)-Interview"},{"method":"test","label":"SC-08(02)-Test"}],"is_enhancement":true,"parent_id":"SC-8"},{"id":"SC-8(3)","oscal_id":"sc-8.3","family":"SC","title":"Cryptographic Protection for Message Externals","statement":"Implement cryptographic mechanisms to protect message externals unless otherwise protected by <alternative physical controls>.","supplemental_guidance":"Cryptographic protection for message externals addresses protection from the unauthorized disclosure of information. Message externals include message headers and routing information. Cryptographic protection prevents the exploitation of message externals and applies to internal and external networks or links that may be visible to individuals who are not authorized users. Header and routing information is sometimes transmitted in clear text (i.e., unencrypted) because the information is not identified by organizations as having significant value or because encrypting the information can result in lower network performance or higher costs. Alternative physical controls include protected distribution systems.","implementation_level":"system","parameters":[{"id":"sc-08.03_odp","label":"alternative physical controls"}],"methods":[{"method":"examine","label":"SC-08(03)-Examine"},{"method":"interview","label":"SC-08(03)-Interview"},{"method":"test","label":"SC-08(03)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-8"},{"id":"SC-8(4)","oscal_id":"sc-8.4","family":"SC","title":"Conceal or Randomize Communications","statement":"Implement cryptographic mechanisms to conceal or randomize communication patterns unless otherwise protected by <alternative physical controls>.","supplemental_guidance":"Concealing or randomizing communication patterns addresses protection from unauthorized disclosure of information. Communication patterns include frequency, periods, predictability, and amount. Changes to communications patterns can reveal information with intelligence value, especially when combined with other available information related to the mission and business functions of the organization. Concealing or randomizing communications prevents the derivation of intelligence based on communications patterns and applies to both internal and external networks or links that may be visible to individuals who are not authorized users. Encrypting the links and transmitting in continuous, fixed, or random patterns prevents the derivation of intelligence from the system communications patterns. Alternative physical controls include protected distribution systems.","implementation_level":"system","parameters":[{"id":"sc-08.04_odp","label":"alternative physical controls"}],"methods":[{"method":"examine","label":"SC-08(04)-Examine"},{"method":"interview","label":"SC-08(04)-Interview"},{"method":"test","label":"SC-08(04)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-8"},{"id":"SC-8(5)","oscal_id":"sc-8.5","family":"SC","title":"Protected Distribution System","statement":"Implement <protected distribution system> to <organization-defined parameter> during transmission.","supplemental_guidance":"The purpose of a protected distribution system is to deter, detect, and/or make difficult physical access to the communication lines that carry national security information.","implementation_level":"system","parameters":[{"id":"sc-08.05_odp.01","label":"protected distribution system"},{"id":"sc-08.05_odp.02","label":"","choices":["prevent unauthorized disclosure of information","detect changes to information"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"SC-08(05)-Examine"},{"method":"interview","label":"SC-08(05)-Interview"},{"method":"test","label":"SC-08(05)-Test"}],"is_enhancement":true,"parent_id":"SC-8"}]},{"id":"SC-9","oscal_id":"sc-9","family":"SC","title":"Transmission Confidentiality","statement":""},{"id":"SC-10","oscal_id":"sc-10","family":"SC","title":"Network Disconnect","statement":"Terminate the network connection associated with a communications session at the end of the session or after <time period> of inactivity.","supplemental_guidance":"Network disconnect applies to internal and external networks. Terminating network connections associated with specific communications sessions includes de-allocating TCP/IP address or port pairs at the operating system level and de-allocating the networking assignments at the application level if multiple application sessions are using a single operating system-level network connection. Periods of inactivity may be established by organizations and include time periods by type of network access or for specific network accesses.","implementation_level":"system","parameters":[{"id":"sc-10_odp","label":"time period"}],"methods":[{"method":"examine","label":"SC-10-Examine"},{"method":"interview","label":"SC-10-Interview"},{"method":"test","label":"SC-10-Test"}],"related_controls":["AC-17","SC-23"]},{"id":"SC-11","oscal_id":"sc-11","family":"SC","title":"Trusted Path","statement":"a. Provide a <organization-defined parameter> isolated trusted communications path for communications between the user and the trusted components of the system; and\nb. Permit users to invoke the trusted communications path for communications between the user and the following security functions of the system, including at a minimum, authentication and re-authentication: <security functions>.","supplemental_guidance":"Trusted paths are mechanisms by which users can communicate (using input devices such as keyboards) directly with the security functions of systems with the requisite assurance to support security policies. Trusted path mechanisms can only be activated by users or the security functions of organizational systems. User responses that occur via trusted paths are protected from modification by and disclosure to untrusted applications. Organizations employ trusted paths for trustworthy, high-assurance connections between security functions of systems and users, including during system logons. The original implementations of trusted paths employed an out-of-band signal to initiate the path, such as using the <BREAK> key, which does not transmit characters that can be spoofed. In later implementations, a key combination that could not be hijacked was used (e.g., the <CTRL> + <ALT> + <DEL> keys). Such key combinations, however, are platform-specific and may not provide a trusted path implementation in every case. The enforcement of trusted communications paths is provided by a specific implementation that meets the reference monitor concept.","implementation_level":"system","parameters":[{"id":"sc-11_odp.01","label":"","choices":["physically","logically"]},{"id":"sc-11_odp.02","label":"security functions"}],"objectives":[{"id":"sc-11_obj.a","label":"SC-11a.","text":"a {{ insert: param, sc-11_odp.01 }} isolated trusted communication path is provided for communications between the user and the trusted components of the system;"},{"id":"sc-11_obj.b","label":"SC-11b.","text":"users are permitted to invoke the trusted communication path for communications between the user and the {{ insert: param, sc-11_odp.02 }} of the system, including authentication and re-authentication, at a minimum."}],"methods":[{"method":"examine","label":"SC-11-Examine"},{"method":"interview","label":"SC-11-Interview"},{"method":"test","label":"SC-11-Test"}],"references":[{"title":"OMB A-130"}],"related_controls":["AC-16","AC-25","SC-12","SC-23"],"enhancements":[{"id":"SC-11(1)","oscal_id":"sc-11.1","family":"SC","title":"Irrefutable Communications Path","statement":"(a) Provide a trusted communications path that is irrefutably distinguishable from other communications paths; and\n(b) Initiate the trusted communications path for communications between the <security functions> of the system and the user.","supplemental_guidance":"An irrefutable communications path permits the system to initiate a trusted path, which necessitates that the user can unmistakably recognize the source of the communication as a trusted system component. For example, the trusted path may appear in an area of the display that other applications cannot access or be based on the presence of an identifier that cannot be spoofed.","implementation_level":"system","parameters":[{"id":"sc-11.01_odp","label":"security functions"}],"objectives":[{"id":"sc-11.1_obj.a","label":"SC-11(01)(a)","text":"a trusted communication path that is irrefutably distinguishable from other communication paths is provided;"},{"id":"sc-11.1_obj.b","label":"SC-11(01)(b)","text":"the trusted communication path for communications between the {{ insert: param, sc-11.01_odp }} of the system and the user is initiated."}],"methods":[{"method":"examine","label":"SC-11(01)-Examine"},{"method":"interview","label":"SC-11(01)-Interview"},{"method":"test","label":"SC-11(01)-Test"}],"is_enhancement":true,"parent_id":"SC-11"}]},{"id":"SC-12","oscal_id":"sc-12","family":"SC","title":"Cryptographic Key Establishment and Management","statement":"Establish and manage cryptographic keys when cryptography is employed within the system in accordance with the following key management requirements: <requirements>.","supplemental_guidance":"Cryptographic key management and establishment can be performed using manual procedures or automated mechanisms with supporting manual procedures. Organizations define key management requirements in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and specify appropriate options, parameters, and levels. Organizations manage trust stores to ensure that only approved trust anchors are part of such trust stores. This includes certificates with visibility external to organizational systems and certificates related to the internal operations of systems. [NIST CMVP](#1acdc775-aafb-4d11-9341-dc6a822e9d38) and [NIST CAVP](#84dc1b0c-acb7-4269-84c4-00dbabacd78c) provide additional information on validated cryptographic modules and algorithms that can be used in cryptographic key management and establishment.","implementation_level":"organization","parameters":[{"id":"sc-12_odp","label":"requirements"}],"objectives":[{"id":"sc-12_obj-1","label":"SC-12[01]","text":"cryptographic keys are established when cryptography is employed within the system in accordance with {{ insert: param, sc-12_odp }};"},{"id":"sc-12_obj-2","label":"SC-12[02]","text":"cryptographic keys are managed when cryptography is employed within the system in accordance with {{ insert: param, sc-12_odp }}."}],"methods":[{"method":"examine","label":"SC-12-Examine"},{"method":"interview","label":"SC-12-Interview"},{"method":"test","label":"SC-12-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"SP 800-56A"},{"title":"SP 800-56B"},{"title":"SP 800-56C"},{"title":"SP 800-57-1"},{"title":"SP 800-57-2"},{"title":"SP 800-57-3"},{"title":"SP 800-63-3"},{"title":"IR 7956"},{"title":"IR 7966"}],"related_controls":["AC-17","AU-9","AU-10","CM-3","IA-3","IA-7","IA-13","SA-4","SA-8","SA-9","SC-8","SC-11","SC-13","SC-17","SC-20","SC-37","SC-40","SI-3","SI-7"],"enhancements":[{"id":"SC-12(1)","oscal_id":"sc-12.1","family":"SC","title":"Availability","statement":"Maintain availability of information in the event of the loss of cryptographic keys by users.","supplemental_guidance":"Escrowing of encryption keys is a common practice for ensuring availability in the event of key loss. A forgotten passphrase is an example of losing a cryptographic key.","implementation_level":"organization","methods":[{"method":"examine","label":"SC-12(01)-Examine"},{"method":"interview","label":"SC-12(01)-Interview"},{"method":"test","label":"SC-12(01)-Test"}],"is_enhancement":true,"parent_id":"SC-12"},{"id":"SC-12(2)","oscal_id":"sc-12.2","family":"SC","title":"Symmetric Keys","statement":"Produce, control, and distribute symmetric cryptographic keys using <organization-defined parameter> key management technology and processes.","supplemental_guidance":"[SP 800-56A](#20957dbb-6a1e-40a2-b38a-66f67d33ac2e), [SP 800-56B](#0d083d8a-5cc6-46f1-8d79-3081d42bcb75) , and [SP 800-56C](#eef62b16-c796-4554-955c-505824135b8a) provide guidance on cryptographic key establishment schemes and key derivation methods. [SP 800-57-1](#110e26af-4765-49e1-8740-6750f83fcda1), [SP 800-57-2](#e7942589-e267-4a5a-a3d9-f39a7aae81f0) , and [SP 800-57-3](#8306620b-1920-4d73-8b21-12008528595f) provide guidance on cryptographic key management.","implementation_level":"organization","parameters":[{"id":"sc-12.02_odp","label":"","choices":["NIST FIPS-validated","NSA-approved"]}],"objectives":[{"id":"sc-12.2_obj-1","label":"SC-12(02)[01]","text":"symmetric cryptographic keys are produced using {{ insert: param, sc-12.02_odp }} key management technology and processes;"},{"id":"sc-12.2_obj-2","label":"SC-12(02)[02]","text":"symmetric cryptographic keys are controlled using {{ insert: param, sc-12.02_odp }} key management technology and processes;"},{"id":"sc-12.2_obj-3","label":"SC-12(02)[03]","text":"symmetric cryptographic keys are distributed using {{ insert: param, sc-12.02_odp }} key management technology and processes."}],"methods":[{"method":"examine","label":"SC-12(02)-Examine"},{"method":"interview","label":"SC-12(02)-Interview"},{"method":"test","label":"SC-12(02)-Test"}],"is_enhancement":true,"parent_id":"SC-12"},{"id":"SC-12(3)","oscal_id":"sc-12.3","family":"SC","title":"Asymmetric Keys","statement":"Produce, control, and distribute asymmetric cryptographic keys using <organization-defined parameter>.","supplemental_guidance":"[SP 800-56A](#20957dbb-6a1e-40a2-b38a-66f67d33ac2e), [SP 800-56B](#0d083d8a-5cc6-46f1-8d79-3081d42bcb75) , and [SP 800-56C](#eef62b16-c796-4554-955c-505824135b8a) provide guidance on cryptographic key establishment schemes and key derivation methods. [SP 800-57-1](#110e26af-4765-49e1-8740-6750f83fcda1), [SP 800-57-2](#e7942589-e267-4a5a-a3d9-f39a7aae81f0) , and [SP 800-57-3](#8306620b-1920-4d73-8b21-12008528595f) provide guidance on cryptographic key management.","implementation_level":"organization","parameters":[{"id":"sc-12.03_odp","label":"","choices":["NSA-approved key management technology and processes","prepositioned keying material","DoD-approved or DoD-issued Medium Assurance PKI certificates","DoD-approved or DoD-issued Medium Hardware Assurance PKI certificates and hardware security tokens that protect the user’s private key","certificates issued in accordance with organization-defined requirements"]}],"objectives":[{"id":"sc-12.3_obj-1","label":"SC-12(03)[01]","text":"asymmetric cryptographic keys are produced using {{ insert: param, sc-12.03_odp }};"},{"id":"sc-12.3_obj-2","label":"SC-12(03)[02]","text":"asymmetric cryptographic keys are controlled using {{ insert: param, sc-12.03_odp }};"},{"id":"sc-12.3_obj-3","label":"SC-12(03)[03]","text":"asymmetric cryptographic keys are distributed using {{ insert: param, sc-12.03_odp }}."}],"methods":[{"method":"examine","label":"SC-12(03)-Examine"},{"method":"interview","label":"SC-12(03)-Interview"},{"method":"test","label":"SC-12(03)-Test"}],"is_enhancement":true,"parent_id":"SC-12"},{"id":"SC-12(4)","oscal_id":"sc-12.4","family":"SC","title":"PKI Certificates","statement":"","is_enhancement":true,"parent_id":"SC-12"},{"id":"SC-12(5)","oscal_id":"sc-12.5","family":"SC","title":"PKI Certificates / Hardware Tokens","statement":"","is_enhancement":true,"parent_id":"SC-12"},{"id":"SC-12(6)","oscal_id":"sc-12.6","family":"SC","title":"Physical Control of Keys","statement":"Maintain physical control of cryptographic keys when stored information is encrypted by external service providers.","supplemental_guidance":"For organizations that use external service providers (e.g., cloud service or data center providers), physical control of cryptographic keys provides additional assurance that information stored by such external providers is not subject to unauthorized disclosure or modification.","implementation_level":"organization","methods":[{"method":"examine","label":"SC-12(06)-Examine"},{"method":"interview","label":"SC-12(06)-Interview"},{"method":"test","label":"SC-12(06)-Test"}],"is_enhancement":true,"parent_id":"SC-12"}]},{"id":"SC-13","oscal_id":"sc-13","family":"SC","title":"Cryptographic Protection","statement":"a. Determine the <cryptographic uses> ; and\nb. Implement the following types of cryptography required for each specified cryptographic use: <types of cryptography>.","supplemental_guidance":"Cryptography can be employed to support a variety of security solutions, including the protection of classified information and controlled unclassified information, the provision and implementation of digital signatures, and the enforcement of information separation when authorized individuals have the necessary clearances but lack the necessary formal access approvals. Cryptography can also be used to support random number and hash generation. Generally applicable cryptographic standards include FIPS-validated cryptography and NSA-approved cryptography. For example, organizations that need to protect classified information may specify the use of NSA-approved cryptography. Organizations that need to provision and implement digital signatures may specify the use of FIPS-validated cryptography. Cryptography is implemented in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.","implementation_level":"system","parameters":[{"id":"sc-13_odp.01","label":"cryptographic uses"},{"id":"sc-13_odp.02","label":"types of cryptography"}],"objectives":[{"id":"sc-13_obj.a","label":"SC-13a.","text":"{{ insert: param, sc-13_odp.01 }} are identified;"},{"id":"sc-13_obj.b","label":"SC-13b.","text":"{{ insert: param, sc-13_odp.02 }} for each specified cryptographic use (defined in SC-13_ODP[01]) are implemented."}],"methods":[{"method":"examine","label":"SC-13-Examine"},{"method":"interview","label":"SC-13-Interview"},{"method":"test","label":"SC-13-Test"}],"references":[{"title":"FIPS 140-3"}],"related_controls":["AC-2","AC-3","AC-7","AC-17","AC-18","AC-19","AU-9","AU-10","CM-11","CP-9","IA-3","IA-5","IA-7","IA-13","MA-4","MP-2","MP-4","MP-5","SA-4","SA-8","SA-9","SC-8","SC-12","SC-20","SC-23","SC-28","SC-40","SI-3","SI-7"],"enhancements":[{"id":"SC-13(1)","oscal_id":"sc-13.1","family":"SC","title":"FIPS-validated Cryptography","statement":"","is_enhancement":true,"parent_id":"SC-13"},{"id":"SC-13(2)","oscal_id":"sc-13.2","family":"SC","title":"NSA-approved Cryptography","statement":"","is_enhancement":true,"parent_id":"SC-13"},{"id":"SC-13(3)","oscal_id":"sc-13.3","family":"SC","title":"Individuals Without Formal Access Approvals","statement":"","is_enhancement":true,"parent_id":"SC-13"},{"id":"SC-13(4)","oscal_id":"sc-13.4","family":"SC","title":"Digital Signatures","statement":"","is_enhancement":true,"parent_id":"SC-13"}]},{"id":"SC-14","oscal_id":"sc-14","family":"SC","title":"Public Access Protections","statement":""},{"id":"SC-15","oscal_id":"sc-15","family":"SC","title":"Collaborative Computing Devices and Applications","statement":"a. Prohibit remote activation of collaborative computing devices and applications with the following exceptions: <exceptions where remote activation is to be allowed> ; and\nb. Provide an explicit indication of use to users physically present at the devices.","supplemental_guidance":"Collaborative computing devices and applications include remote meeting devices and applications, networked white boards, cameras, and microphones. The explicit indication of use includes signals to users when collaborative computing devices and applications are activated.","implementation_level":"system","parameters":[{"id":"sc-15_odp","label":"exceptions where remote activation is to be allowed"}],"objectives":[{"id":"sc-15_obj.a","label":"SC-15a.","text":"remote activation of collaborative computing devices and applications is prohibited except {{ insert: param, sc-15_odp }};"},{"id":"sc-15_obj.b","label":"SC-15b.","text":"an explicit indication of use is provided to users physically present at the devices."}],"methods":[{"method":"examine","label":"SC-15-Examine"},{"method":"interview","label":"SC-15-Interview"},{"method":"test","label":"SC-15-Test"}],"related_controls":["AC-21","SC-42"],"enhancements":[{"id":"SC-15(1)","oscal_id":"sc-15.1","family":"SC","title":"Physical or Logical Disconnect","statement":"Provide <organization-defined parameter> disconnect of collaborative computing devices in a manner that supports ease of use.","supplemental_guidance":"Failing to disconnect from collaborative computing devices can result in subsequent compromises of organizational information. Providing easy methods to disconnect from such devices after a collaborative computing session ensures that participants carry out the disconnect activity without having to go through complex and tedious procedures. Disconnect from collaborative computing devices can be manual or automatic.","implementation_level":"system","parameters":[{"id":"sc-15.01_odp","label":"","choices":["physical","logical"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"SC-15(01)-Examine"},{"method":"interview","label":"SC-15(01)-Interview"},{"method":"test","label":"SC-15(01)-Test"}],"is_enhancement":true,"parent_id":"SC-15"},{"id":"SC-15(2)","oscal_id":"sc-15.2","family":"SC","title":"Blocking Inbound and Outbound Communications Traffic","statement":"","is_enhancement":true,"parent_id":"SC-15"},{"id":"SC-15(3)","oscal_id":"sc-15.3","family":"SC","title":"Disabling and Removal in Secure Work Areas","statement":"Disable or remove collaborative computing devices and applications from <systems or system components> in <secure work areas>.","supplemental_guidance":"Failing to disable or remove collaborative computing devices and applications from systems or system components can result in compromises of information, including eavesdropping on conversations. A Sensitive Compartmented Information Facility (SCIF) is an example of a secure work area.","implementation_level":"organization","parameters":[{"id":"sc-15.03_odp.01","label":"systems or system components"},{"id":"sc-15.03_odp.02","label":"secure work areas"}],"methods":[{"method":"examine","label":"SC-15(03)-Examine"},{"method":"interview","label":"SC-15(03)-Interview"},{"method":"test","label":"SC-15(03)-Test"}],"is_enhancement":true,"parent_id":"SC-15"},{"id":"SC-15(4)","oscal_id":"sc-15.4","family":"SC","title":"Explicitly Indicate Current Participants","statement":"Provide an explicit indication of current participants in <online meetings and teleconferences>.","supplemental_guidance":"Explicitly indicating current participants prevents unauthorized individuals from participating in collaborative computing sessions without the explicit knowledge of other participants.","implementation_level":"system","parameters":[{"id":"sc-15.04_odp","label":"online meetings and teleconferences"}],"methods":[{"method":"examine","label":"SC-15(04)-Examine"},{"method":"interview","label":"SC-15(04)-Interview"},{"method":"test","label":"SC-15(04)-Test"}],"is_enhancement":true,"parent_id":"SC-15"}]},{"id":"SC-16","oscal_id":"sc-16","family":"SC","title":"Transmission of Security and Privacy Attributes","statement":"Associate <organization-defined security and privacy attributes> with information exchanged between systems and between system components.","supplemental_guidance":"Security and privacy attributes can be explicitly or implicitly associated with the information contained in organizational systems or system components. Attributes are abstractions that represent the basic properties or characteristics of an entity with respect to protecting information or the management of personally identifiable information. Attributes are typically associated with internal data structures, including records, buffers, and files within the system. Security and privacy attributes are used to implement access control and information flow control policies; reflect special dissemination, management, or distribution instructions, including permitted uses of personally identifiable information; or support other aspects of the information security and privacy policies. Privacy attributes may be used independently or in conjunction with security attributes.","implementation_level":"system","parameters":[{"id":"sc-16_prm_1","label":"organization-defined security and privacy attributes"},{"id":"sc-16_odp.01","label":"security attributes"},{"id":"sc-16_odp.02","label":"privacy attributes"}],"objectives":[{"id":"sc-16_obj-1","label":"SC-16[01]","text":"{{ insert: param, sc-16_odp.01 }} are associated with information exchanged between systems;"},{"id":"sc-16_obj-2","label":"SC-16[02]","text":"{{ insert: param, sc-16_odp.01 }} are associated with information exchanged between system components;"},{"id":"sc-16_obj-3","label":"SC-16[03]","text":"{{ insert: param, sc-16_odp.02 }} are associated with information exchanged between systems;"},{"id":"sc-16_obj-4","label":"SC-16[04]","text":"{{ insert: param, sc-16_odp.02 }} are associated with information exchanged between system components."}],"methods":[{"method":"examine","label":"SC-16-Examine"},{"method":"interview","label":"SC-16-Interview"},{"method":"test","label":"SC-16-Test"}],"references":[{"title":"OMB A-130"}],"related_controls":["AC-3","AC-4","AC-16"],"enhancements":[{"id":"SC-16(1)","oscal_id":"sc-16.1","family":"SC","title":"Integrity Verification","statement":"Verify the integrity of transmitted security and privacy attributes.","supplemental_guidance":"Part of verifying the integrity of transmitted information is ensuring that security and privacy attributes that are associated with such information have not been modified in an unauthorized manner. Unauthorized modification of security or privacy attributes can result in a loss of integrity for transmitted information.","implementation_level":"system","objectives":[{"id":"sc-16.1_obj-1","label":"SC-16(01)[01]","text":"the integrity of transmitted security attributes is verified;"},{"id":"sc-16.1_obj-2","label":"SC-16(01)[02]","text":"the integrity of transmitted privacy attributes is verified."}],"methods":[{"method":"examine","label":"SC-16(01)-Examine"},{"method":"interview","label":"SC-16(01)-Interview"},{"method":"test","label":"SC-16(01)-Test"}],"related_controls":["AU-10","SC-8"],"is_enhancement":true,"parent_id":"SC-16"},{"id":"SC-16(2)","oscal_id":"sc-16.2","family":"SC","title":"Anti-spoofing Mechanisms","statement":"Implement anti-spoofing mechanisms to prevent adversaries from falsifying the security attributes indicating the successful application of the security process.","supplemental_guidance":"Some attack vectors operate by altering the security attributes of an information system to intentionally and maliciously implement an insufficient level of security within the system. The alteration of attributes leads organizations to believe that a greater number of security functions are in place and operational than have actually been implemented.","implementation_level":"system","methods":[{"method":"examine","label":"SC-16(02)-Examine"},{"method":"interview","label":"SC-16(02)-Interview"},{"method":"test","label":"SC-16(02)-Test"}],"related_controls":["SI-3","SI-4","SI-7"],"is_enhancement":true,"parent_id":"SC-16"},{"id":"SC-16(3)","oscal_id":"sc-16.3","family":"SC","title":"Cryptographic Binding","statement":"Implement <mechanisms or techniques> to bind security and privacy attributes to transmitted information.","supplemental_guidance":"Cryptographic mechanisms and techniques can provide strong security and privacy attribute binding to transmitted information to help ensure the integrity of such information.","implementation_level":"system","parameters":[{"id":"sc-16.03_odp","label":"mechanisms or techniques"}],"methods":[{"method":"examine","label":"SC-16(03)-Examine"},{"method":"interview","label":"SC-16(03)-Interview"},{"method":"test","label":"SC-16(03)-Test"}],"related_controls":["AC-16","SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-16"}]},{"id":"SC-17","oscal_id":"sc-17","family":"SC","title":"Public Key Infrastructure Certificates","statement":"a. Issue public key certificates under an <certificate policy> or obtain public key certificates from an approved service provider; and\nb. Include only approved trust anchors in trust stores or certificate stores managed by the organization.","supplemental_guidance":"Public key infrastructure (PKI) certificates are certificates with visibility external to organizational systems and certificates related to the internal operations of systems, such as application-specific time services. In cryptographic systems with a hierarchical structure, a trust anchor is an authoritative source (i.e., a certificate authority) for which trust is assumed and not derived. A root certificate for a PKI system is an example of a trust anchor. A trust store or certificate store maintains a list of trusted root certificates.","implementation_level":"organization","parameters":[{"id":"sc-17_odp","label":"certificate policy"}],"objectives":[{"id":"sc-17_obj.a","label":"SC-17a.","text":"public key certificates are issued under {{ insert: param, sc-17_odp }} , or public key certificates are obtained from an approved service provider;"},{"id":"sc-17_obj.b","label":"SC-17b.","text":"only approved trust anchors are included in trust stores or certificate stores managed by the organization."}],"methods":[{"method":"examine","label":"SC-17-Examine"},{"method":"interview","label":"SC-17-Interview"},{"method":"test","label":"SC-17-Test"}],"references":[{"title":"SP 800-32"},{"title":"SP 800-57-1"},{"title":"SP 800-57-2"},{"title":"SP 800-57-3"},{"title":"SP 800-63-3"}],"related_controls":["AU-10","IA-5","SC-12"]},{"id":"SC-18","oscal_id":"sc-18","family":"SC","title":"Mobile Code","statement":"a. Define acceptable and unacceptable mobile code and mobile code technologies; and\nb. Authorize, monitor, and control the use of mobile code within the system.","supplemental_guidance":"Mobile code includes any program, application, or content that can be transmitted across a network (e.g., embedded in an email, document, or website) and executed on a remote system. Decisions regarding the use of mobile code within organizational systems are based on the potential for the code to cause damage to the systems if used maliciously. Mobile code technologies include Java applets, JavaScript, HTML5, WebGL, and VBScript. Usage restrictions and implementation guidelines apply to both the selection and use of mobile code installed on servers and mobile code downloaded and executed on individual workstations and devices, including notebook computers and smart phones. Mobile code policy and procedures address specific actions taken to prevent the development, acquisition, and introduction of unacceptable mobile code within organizational systems, including requiring mobile code to be digitally signed by a trusted source.","implementation_level":"organization","objectives":[{"id":"sc-18_obj.a-1","label":"SC-18a.[01]","text":"acceptable mobile code is defined;"},{"id":"sc-18_obj.a-2","label":"SC-18a.[02]","text":"unacceptable mobile code is defined;"},{"id":"sc-18_obj.a-3","label":"SC-18a.[03]","text":"acceptable mobile code technologies are defined;"},{"id":"sc-18_obj.a-4","label":"SC-18a.[04]","text":"unacceptable mobile code technologies are defined;"},{"id":"sc-18_obj.b-1","label":"SC-18b.[01]","text":"the use of mobile code is authorized within the system;"},{"id":"sc-18_obj.b-2","label":"SC-18b.[02]","text":"the use of mobile code is monitored within the system;"},{"id":"sc-18_obj.b-3","label":"SC-18b.[03]","text":"the use of mobile code is controlled within the system."}],"methods":[{"method":"examine","label":"SC-18-Examine"},{"method":"interview","label":"SC-18-Interview"},{"method":"test","label":"SC-18-Test"}],"references":[{"title":"SP 800-28"}],"related_controls":["AU-2","AU-12","CM-2","CM-6","SI-3"],"enhancements":[{"id":"SC-18(1)","oscal_id":"sc-18.1","family":"SC","title":"Identify Unacceptable Code and Take Corrective Actions","statement":"Identify <unacceptable mobile code> and take <corrective actions>.","supplemental_guidance":"Corrective actions when unacceptable mobile code is detected include blocking, quarantine, or alerting administrators. Blocking includes preventing the transmission of word processing files with embedded macros when such macros have been determined to be unacceptable mobile code.","implementation_level":"system","parameters":[{"id":"sc-18.01_odp.01","label":"unacceptable mobile code"},{"id":"sc-18.01_odp.02","label":"corrective actions"}],"objectives":[{"id":"sc-18.1_obj-1","label":"SC-18(01)[01]","text":"{{ insert: param, sc-18.01_odp.01 }} is identified;"},{"id":"sc-18.1_obj-2","label":"SC-18(01)[02]","text":"{{ insert: param, sc-18.01_odp.02 }} are taken if unacceptable mobile code is identified."}],"methods":[{"method":"examine","label":"SC-18(01)-Examine"},{"method":"interview","label":"SC-18(01)-Interview"},{"method":"test","label":"SC-18(01)-Test"}],"is_enhancement":true,"parent_id":"SC-18"},{"id":"SC-18(2)","oscal_id":"sc-18.2","family":"SC","title":"Acquisition, Development, and Use","statement":"Verify that the acquisition, development, and use of mobile code to be deployed in the system meets <mobile code requirements>.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"sc-18.02_odp","label":"mobile code requirements"}],"objectives":[{"id":"sc-18.2_obj-1","label":"SC-18(02)[01]","text":"the acquisition of mobile code to be deployed in the system meets {{ insert: param, sc-18.02_odp }};"},{"id":"sc-18.2_obj-2","label":"SC-18(02)[02]","text":"the development of mobile code to be deployed in the system meets {{ insert: param, sc-18.02_odp }};"},{"id":"sc-18.2_obj-3","label":"SC-18(02)[03]","text":"the use of mobile code to be deployed in the system meets {{ insert: param, sc-18.02_odp }}."}],"methods":[{"method":"examine","label":"SC-18(02)-Examine"},{"method":"interview","label":"SC-18(02)-Interview"},{"method":"test","label":"SC-18(02)-Test"}],"is_enhancement":true,"parent_id":"SC-18"},{"id":"SC-18(3)","oscal_id":"sc-18.3","family":"SC","title":"Prevent Downloading and Execution","statement":"Prevent the download and execution of <unacceptable mobile code>.","supplemental_guidance":"None.","implementation_level":"system","parameters":[{"id":"sc-18.03_odp","label":"unacceptable mobile code"}],"objectives":[{"id":"sc-18.3_obj-1","label":"SC-18(03)[01]","text":"the download of {{ insert: param, sc-18.03_odp }} is prevented;"},{"id":"sc-18.3_obj-2","label":"SC-18(03)[02]","text":"the execution of {{ insert: param, sc-18.03_odp }} is prevented."}],"methods":[{"method":"examine","label":"SC-18(03)-Examine"},{"method":"interview","label":"SC-18(03)-Interview"},{"method":"test","label":"SC-18(03)-Test"}],"is_enhancement":true,"parent_id":"SC-18"},{"id":"SC-18(4)","oscal_id":"sc-18.4","family":"SC","title":"Prevent Automatic Execution","statement":"Prevent the automatic execution of mobile code in <software applications> and enforce <actions> prior to executing the code.","supplemental_guidance":"Actions enforced before executing mobile code include prompting users prior to opening email attachments or clicking on web links. Preventing the automatic execution of mobile code includes disabling auto-execute features on system components that employ portable storage devices, such as compact discs, digital versatile discs, and universal serial bus devices.","implementation_level":"system","parameters":[{"id":"sc-18.04_odp.01","label":"software applications"},{"id":"sc-18.04_odp.02","label":"actions"}],"objectives":[{"id":"sc-18.4_obj-1","label":"SC-18(04)[01]","text":"the automatic execution of mobile code in {{ insert: param, sc-18.04_odp.01 }} is prevented;"},{"id":"sc-18.4_obj-2","label":"SC-18(04)[02]","text":"{{ insert: param, sc-18.04_odp.02 }} are enforced prior to executing mobile code."}],"methods":[{"method":"examine","label":"SC-18(04)-Examine"},{"method":"interview","label":"SC-18(04)-Interview"},{"method":"test","label":"SC-18(04)-Test"}],"is_enhancement":true,"parent_id":"SC-18"},{"id":"SC-18(5)","oscal_id":"sc-18.5","family":"SC","title":"Allow Execution Only in Confined Environments","statement":"Allow execution of permitted mobile code only in confined virtual machine environments.","supplemental_guidance":"Permitting the execution of mobile code only in confined virtual machine environments helps prevent the introduction of malicious code into other systems and system components.","implementation_level":"system","methods":[{"method":"examine","label":"SC-18(05)-Examine"},{"method":"interview","label":"SC-18(05)-Interview"},{"method":"test","label":"SC-18(05)-Test"}],"related_controls":["SC-44","SI-7"],"is_enhancement":true,"parent_id":"SC-18"}]},{"id":"SC-19","oscal_id":"sc-19","family":"SC","title":"Voice Over Internet Protocol","statement":"Technology-specific; addressed as any other technology or protocol."},{"id":"SC-20","oscal_id":"sc-20","family":"SC","title":"Secure Name/Address Resolution Service (Authoritative Source)","statement":"a. Provide additional data origin authentication and integrity verification artifacts along with the authoritative name resolution data the system returns in response to external name/address resolution queries; and\nb. Provide the means to indicate the security status of child zones and (if the child supports secure resolution services) to enable verification of a chain of trust among parent and child domains, when operating as part of a distributed, hierarchical namespace.","supplemental_guidance":"Providing authoritative source information enables external clients, including remote Internet clients, to obtain origin authentication and integrity verification assurances for the host/service name to network address resolution information obtained through the service. Systems that provide name and address resolution services include domain name system (DNS) servers. Additional artifacts include DNS Security Extensions (DNSSEC) digital signatures and cryptographic keys. Authoritative data includes DNS resource records. The means for indicating the security status of child zones include the use of delegation signer resource records in the DNS. Systems that use technologies other than the DNS to map between host and service names and network addresses provide other means to assure the authenticity and integrity of response data.","implementation_level":"system","objectives":[{"id":"sc-20_obj.a-1","label":"SC-20a.[01]","text":"additional data origin authentication is provided along with the authoritative name resolution data that the system returns in response to external name/address resolution queries;"},{"id":"sc-20_obj.a-2","label":"SC-20a.[02]","text":"integrity verification artifacts are provided along with the authoritative name resolution data that the system returns in response to external name/address resolution queries;"},{"id":"sc-20_obj.b-1","label":"SC-20b.[01]","text":"the means to indicate the security status of child zones (and if the child supports secure resolution services) is provided when operating as part of a distributed, hierarchical namespace;"},{"id":"sc-20_obj.b-2","label":"SC-20b.[02]","text":"the means to enable verification of a chain of trust among parent and child domains when operating as part of a distributed, hierarchical namespace is provided."}],"methods":[{"method":"examine","label":"SC-20-Examine"},{"method":"interview","label":"SC-20-Interview"},{"method":"test","label":"SC-20-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 186-4"},{"title":"SP 800-81-2"}],"related_controls":["AU-10","SC-8","SC-12","SC-13","SC-21","SC-22"],"enhancements":[{"id":"SC-20(1)","oscal_id":"sc-20.1","family":"SC","title":"Child Subspaces","statement":"","is_enhancement":true,"parent_id":"SC-20"},{"id":"SC-20(2)","oscal_id":"sc-20.2","family":"SC","title":"Data Origin and Integrity","statement":"Provide data origin and integrity protection artifacts for internal name/address resolution queries.","supplemental_guidance":"None.","implementation_level":"system","objectives":[{"id":"sc-20.2_obj-1","label":"SC-20(02)[01]","text":"data origin artifacts are provided for internal name/address resolution queries;"},{"id":"sc-20.2_obj-2","label":"SC-20(02)[02]","text":"integrity protection artifacts are provided for internal name/address resolution queries."}],"methods":[{"method":"examine","label":"SC-20(02)-Examine"},{"method":"interview","label":"SC-20(02)-Interview"},{"method":"test","label":"SC-20(02)-Test"}],"is_enhancement":true,"parent_id":"SC-20"}]},{"id":"SC-21","oscal_id":"sc-21","family":"SC","title":"Secure Name/Address Resolution Service (Recursive or Caching Resolver)","statement":"Request and perform data origin authentication and data integrity verification on the name/address resolution responses the system receives from authoritative sources.","supplemental_guidance":"Each client of name resolution services either performs this validation on its own or has authenticated channels to trusted validation providers. Systems that provide name and address resolution services for local clients include recursive resolving or caching domain name system (DNS) servers. DNS client resolvers either perform validation of DNSSEC signatures, or clients use authenticated channels to recursive resolvers that perform such validations. Systems that use technologies other than the DNS to map between host and service names and network addresses provide some other means to enable clients to verify the authenticity and integrity of response data.","implementation_level":"system","objectives":[{"id":"sc-21_obj-1","label":"SC-21[01]","text":"data origin authentication is requested for the name/address resolution responses that the system receives from authoritative sources;"},{"id":"sc-21_obj-2","label":"SC-21[02]","text":"data origin authentication is performed on the name/address resolution responses that the system receives from authoritative sources;"},{"id":"sc-21_obj-3","label":"SC-21[03]","text":"data integrity verification is requested for the name/address resolution responses that the system receives from authoritative sources;"},{"id":"sc-21_obj-4","label":"SC-21[04]","text":"data integrity verification is performed on the name/address resolution responses that the system receives from authoritative sources."}],"methods":[{"method":"examine","label":"SC-21-Examine"},{"method":"interview","label":"SC-21-Interview"},{"method":"test","label":"SC-21-Test"}],"references":[{"title":"SP 800-81-2"}],"related_controls":["SC-20","SC-22"],"enhancements":[{"id":"SC-21(1)","oscal_id":"sc-21.1","family":"SC","title":"Data Origin and Integrity","statement":"","is_enhancement":true,"parent_id":"SC-21"}]},{"id":"SC-22","oscal_id":"sc-22","family":"SC","title":"Architecture and Provisioning for Name/Address Resolution Service","statement":"Ensure the systems that collectively provide name/address resolution service for an organization are fault-tolerant and implement internal and external role separation.","supplemental_guidance":"Systems that provide name and address resolution services include domain name system (DNS) servers. To eliminate single points of failure in systems and enhance redundancy, organizations employ at least two authoritative domain name system servers—one configured as the primary server and the other configured as the secondary server. Additionally, organizations typically deploy the servers in two geographically separated network subnetworks (i.e., not located in the same physical facility). For role separation, DNS servers with internal roles only process name and address resolution requests from within organizations (i.e., from internal clients). DNS servers with external roles only process name and address resolution information requests from clients external to organizations (i.e., on external networks, including the Internet). Organizations specify clients that can access authoritative DNS servers in certain roles (e.g., by address ranges and explicit lists).","implementation_level":"system","objectives":[{"id":"sc-22_obj-1","label":"SC-22[01]","text":"the systems that collectively provide name/address resolution services for an organization are fault-tolerant;"},{"id":"sc-22_obj-2","label":"SC-22[02]","text":"the systems that collectively provide name/address resolution services for an organization implement internal role separation;"},{"id":"sc-22_obj-3","label":"SC-22[03]","text":"the systems that collectively provide name/address resolution services for an organization implement external role separation."}],"methods":[{"method":"examine","label":"SC-22-Examine"},{"method":"interview","label":"SC-22-Interview"},{"method":"test","label":"SC-22-Test"}],"references":[{"title":"SP 800-81-2"}],"related_controls":["SC-2","SC-20","SC-21","SC-24"]},{"id":"SC-23","oscal_id":"sc-23","family":"SC","title":"Session Authenticity","statement":"Protect the authenticity of communications sessions.","supplemental_guidance":"Protecting session authenticity addresses communications protection at the session level, not at the packet level. Such protection establishes grounds for confidence at both ends of communications sessions in the ongoing identities of other parties and the validity of transmitted information. Authenticity protection includes protecting against \"man-in-the-middle\" attacks, session hijacking, and the insertion of false information into sessions.","implementation_level":"system","methods":[{"method":"examine","label":"SC-23-Examine"},{"method":"interview","label":"SC-23-Interview"},{"method":"test","label":"SC-23-Test"}],"references":[{"title":"SP 800-52"},{"title":"SP 800-77"},{"title":"SP 800-95"},{"title":"SP 800-113"}],"related_controls":["AU-10","SC-8","SC-10","SC-11"],"enhancements":[{"id":"SC-23(1)","oscal_id":"sc-23.1","family":"SC","title":"Invalidate Session Identifiers at Logout","statement":"Invalidate session identifiers upon user logout or other session termination.","supplemental_guidance":"Invalidating session identifiers at logout curtails the ability of adversaries to capture and continue to employ previously valid session IDs.","implementation_level":"system","methods":[{"method":"examine","label":"SC-23(01)-Examine"},{"method":"interview","label":"SC-23(01)-Interview"},{"method":"test","label":"SC-23(01)-Test"}],"is_enhancement":true,"parent_id":"SC-23"},{"id":"SC-23(2)","oscal_id":"sc-23.2","family":"SC","title":"User-initiated Logouts and Message Displays","statement":"","is_enhancement":true,"parent_id":"SC-23"},{"id":"SC-23(3)","oscal_id":"sc-23.3","family":"SC","title":"Unique System-generated Session Identifiers","statement":"Generate a unique session identifier for each session with <randomness requirements> and recognize only session identifiers that are system-generated.","supplemental_guidance":"Generating unique session identifiers curtails the ability of adversaries to reuse previously valid session IDs. Employing the concept of randomness in the generation of unique session identifiers protects against brute-force attacks to determine future session identifiers.","implementation_level":"system","parameters":[{"id":"sc-23.03_odp","label":"randomness requirements"}],"objectives":[{"id":"sc-23.3_obj-1","label":"SC-23(03)[01]","text":"a unique session identifier is generated for each session with {{ insert: param, sc-23.03_odp }};"},{"id":"sc-23.3_obj-2","label":"SC-23(03)[02]","text":"only system-generated session identifiers are recognized."}],"methods":[{"method":"examine","label":"SC-23(03)-Examine"},{"method":"interview","label":"SC-23(03)-Interview"},{"method":"test","label":"SC-23(03)-Test"}],"related_controls":["AC-10","SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-23"},{"id":"SC-23(4)","oscal_id":"sc-23.4","family":"SC","title":"Unique Session Identifiers with Randomization","statement":"","is_enhancement":true,"parent_id":"SC-23"},{"id":"SC-23(5)","oscal_id":"sc-23.5","family":"SC","title":"Allowed Certificate Authorities","statement":"Only allow the use of <certificated authorities> for verification of the establishment of protected sessions.","supplemental_guidance":"Reliance on certificate authorities for the establishment of secure sessions includes the use of Transport Layer Security (TLS) certificates. These certificates, after verification by their respective certificate authorities, facilitate the establishment of protected sessions between web clients and web servers.","implementation_level":"system","parameters":[{"id":"sc-23.05_odp","label":"certificated authorities"}],"methods":[{"method":"examine","label":"SC-23(05)-Examine"},{"method":"interview","label":"SC-23(05)-Interview"},{"method":"test","label":"SC-23(05)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-23"}]},{"id":"SC-24","oscal_id":"sc-24","family":"SC","title":"Fail in Known State","statement":"Fail to a <known system state> for the following failures on the indicated components while preserving <system state information> in failure: <types of system failures on system components>.","supplemental_guidance":"Failure in a known state addresses security concerns in accordance with the mission and business needs of organizations. Failure in a known state prevents the loss of confidentiality, integrity, or availability of information in the event of failures of organizational systems or system components. Failure in a known safe state helps to prevent systems from failing to a state that may cause injury to individuals or destruction to property. Preserving system state information facilitates system restart and return to the operational mode with less disruption of mission and business processes.","implementation_level":"system","parameters":[{"id":"sc-24_odp.01","label":"types of system failures on system components"},{"id":"sc-24_odp.02","label":"known system state"},{"id":"sc-24_odp.03","label":"system state information"}],"methods":[{"method":"examine","label":"SC-24-Examine"},{"method":"interview","label":"SC-24-Interview"},{"method":"test","label":"SC-24-Test"}],"related_controls":["CP-2","CP-4","CP-10","CP-12","SA-8","SC-7","SC-22","SI-13"]},{"id":"SC-25","oscal_id":"sc-25","family":"SC","title":"Thin Nodes","statement":"Employ minimal functionality and information storage on the following system components: <system components>.","supplemental_guidance":"The deployment of system components with minimal functionality reduces the need to secure every endpoint and may reduce the exposure of information, systems, and services to attacks. Reduced or minimal functionality includes diskless nodes and thin client technologies.","implementation_level":"system","parameters":[{"id":"sc-25_odp","label":"system components"}],"objectives":[{"id":"sc-25_obj-1","label":"SC-25[01]","text":"minimal functionality for {{ insert: param, sc-25_odp }} is employed;"},{"id":"sc-25_obj-2","label":"SC-25[02]","text":"minimal information storage on {{ insert: param, sc-25_odp }} is allocated."}],"methods":[{"method":"examine","label":"SC-25-Examine"},{"method":"interview","label":"SC-25-Interview"},{"method":"test","label":"SC-25-Test"}],"related_controls":["SC-30","SC-44"]},{"id":"SC-26","oscal_id":"sc-26","family":"SC","title":"Decoys","statement":"Include components within organizational systems specifically designed to be the target of malicious attacks for detecting, deflecting, and analyzing such attacks.","supplemental_guidance":"Decoys (i.e., honeypots, honeynets, or deception nets) are established to attract adversaries and deflect attacks away from the operational systems that support organizational mission and business functions. Use of decoys requires some supporting isolation measures to ensure that any deflected malicious code does not infect organizational systems. Depending on the specific usage of the decoy, consultation with the Office of the General Counsel before deployment may be needed.","implementation_level":"system","objectives":[{"id":"sc-26_obj-1","label":"SC-26[01]","text":"components within organizational systems specifically designed to be the target of malicious attacks are included to detect such attacks;"},{"id":"sc-26_obj-2","label":"SC-26[02]","text":"components within organizational systems specifically designed to be the target of malicious attacks are included to deflect such attacks;"},{"id":"sc-26_obj-3","label":"SC-26[03]","text":"components within organizational systems specifically designed to be the target of malicious attacks are included to analyze such attacks."}],"methods":[{"method":"examine","label":"SC-26-Examine"},{"method":"interview","label":"SC-26-Interview"},{"method":"test","label":"SC-26-Test"}],"related_controls":["RA-5","SC-7","SC-30","SC-35","SC-44","SI-3","SI-4"],"enhancements":[{"id":"SC-26(1)","oscal_id":"sc-26.1","family":"SC","title":"Detection of Malicious Code","statement":"","is_enhancement":true,"parent_id":"SC-26"}]},{"id":"SC-27","oscal_id":"sc-27","family":"SC","title":"Platform-independent Applications","statement":"Include within organizational systems the following platform independent applications: <platform-independent applications>.","supplemental_guidance":"Platforms are combinations of hardware, firmware, and software components used to execute software applications. Platforms include operating systems, the underlying computer architectures, or both. Platform-independent applications are applications with the capability to execute on multiple platforms. Such applications promote portability and reconstitution on different platforms. Application portability and the ability to reconstitute on different platforms increase the availability of mission-essential functions within organizations in situations where systems with specific operating systems are under attack.","implementation_level":"system","parameters":[{"id":"sc-27_odp","label":"platform-independent applications"}],"methods":[{"method":"examine","label":"SC-27-Examine"},{"method":"interview","label":"SC-27-Interview"},{"method":"test","label":"SC-27-Test"}],"related_controls":["SC-29"]},{"id":"SC-28","oscal_id":"sc-28","family":"SC","title":"Protection of Information at Rest","statement":"Protect the <organization-defined parameter> of the following information at rest: <information at rest>.","supplemental_guidance":"Information at rest refers to the state of information when it is not in process or in transit and is located on system components. Such components include internal or external hard disk drives, storage area network devices, or databases. However, the focus of protecting information at rest is not on the type of storage device or frequency of access but rather on the state of the information. Information at rest addresses the confidentiality and integrity of information and covers user information and system information. System-related information that requires protection includes configurations or rule sets for firewalls, intrusion detection and prevention systems, filtering routers, and authentication information. Organizations may employ different mechanisms to achieve confidentiality and integrity protections, including the use of cryptographic mechanisms and file share scanning. Integrity protection can be achieved, for example, by implementing write-once-read-many (WORM) technologies. When adequate protection of information at rest cannot otherwise be achieved, organizations may employ other controls, including frequent scanning to identify malicious code at rest and secure offline storage in lieu of online storage.","implementation_level":"system","parameters":[{"id":"sc-28_odp.01","label":"","choices":["confidentiality","integrity"],"how_many":"one-or-more"},{"id":"sc-28_odp.02","label":"information at rest"}],"methods":[{"method":"examine","label":"SC-28-Examine"},{"method":"interview","label":"SC-28-Interview"},{"method":"test","label":"SC-28-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-56A"},{"title":"SP 800-56B"},{"title":"SP 800-56C"},{"title":"SP 800-57-1"},{"title":"SP 800-57-2"},{"title":"SP 800-57-3"},{"title":"SP 800-111"},{"title":"SP 800-124"}],"related_controls":["AC-3","AC-4","AC-6","AC-19","CA-7","CM-3","CM-5","CM-6","CP-9","MP-4","MP-5","PE-3","SC-8","SC-12","SC-13","SC-34","SI-3","SI-7","SI-16"],"enhancements":[{"id":"SC-28(1)","oscal_id":"sc-28.1","family":"SC","title":"Cryptographic Protection","statement":"Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of the following information at rest on <system components or media>: <information>.","supplemental_guidance":"The selection of cryptographic mechanisms is based on the need to protect the confidentiality and integrity of organizational information. The strength of mechanism is commensurate with the security category or classification of the information. Organizations have the flexibility to encrypt information on system components or media or encrypt data structures, including files, records, or fields.","implementation_level":"system","parameters":[{"id":"sc-28.01_odp.01","label":"information"},{"id":"sc-28.01_odp.02","label":"system components or media"}],"objectives":[{"id":"sc-28.1_obj-1","label":"SC-28(01)[01]","text":"cryptographic mechanisms are implemented to prevent unauthorized disclosure of {{ insert: param, sc-28.01_odp.01 }} at rest on {{ insert: param, sc-28.01_odp.02 }};"},{"id":"sc-28.1_obj-2","label":"SC-28(01)[02]","text":"cryptographic mechanisms are implemented to prevent unauthorized modification of {{ insert: param, sc-28.01_odp.01 }} at rest on {{ insert: param, sc-28.01_odp.02 }}."}],"methods":[{"method":"examine","label":"SC-28(01)-Examine"},{"method":"interview","label":"SC-28(01)-Interview"},{"method":"test","label":"SC-28(01)-Test"}],"related_controls":["AC-19","SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-28"},{"id":"SC-28(2)","oscal_id":"sc-28.2","family":"SC","title":"Offline Storage","statement":"Remove the following information from online storage and store offline in a secure location: <information>.","supplemental_guidance":"Removing organizational information from online storage to offline storage eliminates the possibility of individuals gaining unauthorized access to the information through a network. Therefore, organizations may choose to move information to offline storage in lieu of protecting such information in online storage.","implementation_level":"organization","parameters":[{"id":"sc-28.02_odp","label":"information"}],"objectives":[{"id":"sc-28.2_obj-1","label":"SC-28(02)[01]","text":"{{ insert: param, sc-28.02_odp }} is removed from online storage;"},{"id":"sc-28.2_obj-2","label":"SC-28(02)[02]","text":"{{ insert: param, sc-28.02_odp }} is stored offline in a secure location."}],"methods":[{"method":"examine","label":"SC-28(02)-Examine"},{"method":"interview","label":"SC-28(02)-Interview"},{"method":"test","label":"SC-28(02)-Test"}],"is_enhancement":true,"parent_id":"SC-28"},{"id":"SC-28(3)","oscal_id":"sc-28.3","family":"SC","title":"Cryptographic Keys","statement":"Provide protected storage for cryptographic keys <organization-defined parameter>.","supplemental_guidance":"A Trusted Platform Module (TPM) is an example of a hardware-protected data store that can be used to protect cryptographic keys.","implementation_level":"organization","parameters":[{"id":"sc-28.03_odp.01","label":"","choices":["{{ insert: param, sc-28.03_odp.02 }} ","hardware-protected key store"]},{"id":"sc-28.03_odp.02","label":"safeguards"}],"methods":[{"method":"examine","label":"SC-28(03)-Examine"},{"method":"interview","label":"SC-28(03)-Interview"},{"method":"test","label":"SC-28(03)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-28"}]},{"id":"SC-29","oscal_id":"sc-29","family":"SC","title":"Heterogeneity","statement":"Employ a diverse set of information technologies for the following system components in the implementation of the system: <system components>.","supplemental_guidance":"Increasing the diversity of information technologies within organizational systems reduces the impact of potential exploitations or compromises of specific technologies. Such diversity protects against common mode failures, including those failures induced by supply chain attacks. Diversity in information technologies also reduces the likelihood that the means adversaries use to compromise one system component will be effective against other system components, thus further increasing the adversary work factor to successfully complete planned attacks. An increase in diversity may add complexity and management overhead that could ultimately lead to mistakes and unauthorized configurations.","implementation_level":"organization","parameters":[{"id":"sc-29_odp","label":"system components"}],"methods":[{"method":"examine","label":"SC-29-Examine"},{"method":"interview","label":"SC-29-Interview"},{"method":"test","label":"SC-29-Test"}],"related_controls":["AU-9","PL-8","SC-27","SC-30","SR-3"],"enhancements":[{"id":"SC-29(1)","oscal_id":"sc-29.1","family":"SC","title":"Virtualization Techniques","statement":"Employ virtualization techniques to support the deployment of a diversity of operating systems and applications that are changed <frequency>.","supplemental_guidance":"While frequent changes to operating systems and applications can pose significant configuration management challenges, the changes can result in an increased work factor for adversaries to conduct successful attacks. Changing virtual operating systems or applications, as opposed to changing actual operating systems or applications, provides virtual changes that impede attacker success while reducing configuration management efforts. Virtualization techniques can assist in isolating untrustworthy software or software of dubious provenance into confined execution environments.","implementation_level":"organization","parameters":[{"id":"sc-29.01_odp","label":"frequency"}],"methods":[{"method":"examine","label":"SC-29(01)-Examine"},{"method":"interview","label":"SC-29(01)-Interview"},{"method":"test","label":"SC-29(01)-Test"}],"is_enhancement":true,"parent_id":"SC-29"}]},{"id":"SC-30","oscal_id":"sc-30","family":"SC","title":"Concealment and Misdirection","statement":"Employ the following concealment and misdirection techniques for <systems> at <time periods> to confuse and mislead adversaries: <concealment and misdirection techniques>.","supplemental_guidance":"Concealment and misdirection techniques can significantly reduce the targeting capabilities of adversaries (i.e., window of opportunity and available attack surface) to initiate and complete attacks. For example, virtualization techniques provide organizations with the ability to disguise systems, potentially reducing the likelihood of successful attacks without the cost of having multiple platforms. The increased use of concealment and misdirection techniques and methods—including randomness, uncertainty, and virtualization—may sufficiently confuse and mislead adversaries and subsequently increase the risk of discovery and/or exposing tradecraft. Concealment and misdirection techniques may provide additional time to perform core mission and business functions. The implementation of concealment and misdirection techniques may add to the complexity and management overhead required for the system.","implementation_level":"organization","parameters":[{"id":"sc-30_odp.01","label":"concealment and misdirection techniques"},{"id":"sc-30_odp.02","label":"systems"},{"id":"sc-30_odp.03","label":"time periods"}],"methods":[{"method":"examine","label":"SC-30-Examine"},{"method":"interview","label":"SC-30-Interview"},{"method":"test","label":"SC-30-Test"}],"related_controls":["AC-6","SC-25","SC-26","SC-29","SC-44","SI-14"],"enhancements":[{"id":"SC-30(1)","oscal_id":"sc-30.1","family":"SC","title":"Virtualization Techniques","statement":"","is_enhancement":true,"parent_id":"SC-30"},{"id":"SC-30(2)","oscal_id":"sc-30.2","family":"SC","title":"Randomness","statement":"Employ <techniques> to introduce randomness into organizational operations and assets.","supplemental_guidance":"Randomness introduces increased levels of uncertainty for adversaries regarding the actions that organizations take to defend their systems against attacks. Such actions may impede the ability of adversaries to correctly target information resources of organizations that support critical missions or business functions. Uncertainty may also cause adversaries to hesitate before initiating or continuing attacks. Misdirection techniques that involve randomness include performing certain routine actions at different times of day, employing different information technologies, using different suppliers, and rotating roles and responsibilities of organizational personnel.","implementation_level":"organization","parameters":[{"id":"sc-30.02_odp","label":"techniques"}],"methods":[{"method":"examine","label":"SC-30(02)-Examine"},{"method":"interview","label":"SC-30(02)-Interview"},{"method":"test","label":"SC-30(02)-Test"}],"is_enhancement":true,"parent_id":"SC-30"},{"id":"SC-30(3)","oscal_id":"sc-30.3","family":"SC","title":"Change Processing and Storage Locations","statement":"Change the location of <processing and/or storage> <organization-defined parameter>].","supplemental_guidance":"Adversaries target critical mission and business functions and the systems that support those mission and business functions while also trying to minimize the exposure of their existence and tradecraft. The static, homogeneous, and deterministic nature of organizational systems targeted by adversaries make such systems more susceptible to attacks with less adversary cost and effort to be successful. Changing processing and storage locations (also referred to as moving target defense) addresses the advanced persistent threat using techniques such as virtualization, distributed processing, and replication. This enables organizations to relocate the system components (i.e., processing, storage) that support critical mission and business functions. Changing the locations of processing activities and/or storage sites introduces a degree of uncertainty into the targeting activities of adversaries. The targeting uncertainty increases the work factor of adversaries and makes compromises or breaches of the organizational systems more difficult and time-consuming. It also increases the chances that adversaries may inadvertently disclose certain aspects of their tradecraft while attempting to locate critical organizational resources.","implementation_level":"organization","parameters":[{"id":"sc-30.03_odp.01","label":"processing and/or storage"},{"id":"sc-30.03_odp.02","label":"","choices":["{{ insert: param, sc-30.03_odp.03 }} ","random time intervals"]},{"id":"sc-30.03_odp.03","label":"time frequency"}],"methods":[{"method":"examine","label":"SC-30(03)-Examine"},{"method":"interview","label":"SC-30(03)-Interview"},{"method":"test","label":"SC-30(03)-Test"}],"is_enhancement":true,"parent_id":"SC-30"},{"id":"SC-30(4)","oscal_id":"sc-30.4","family":"SC","title":"Misleading Information","statement":"Employ realistic, but misleading information in <system components> about its security state or posture.","supplemental_guidance":"Employing misleading information is intended to confuse potential adversaries regarding the nature and extent of controls deployed by organizations. Thus, adversaries may employ incorrect and ineffective attack techniques. One technique for misleading adversaries is for organizations to place misleading information regarding the specific controls deployed in external systems that are known to be targeted by adversaries. Another technique is the use of deception nets that mimic actual aspects of organizational systems but use, for example, out-of-date software configurations.","implementation_level":"organization","parameters":[{"id":"sc-30.04_odp","label":"system components"}],"methods":[{"method":"examine","label":"SC-30(04)-Examine"},{"method":"interview","label":"SC-30(04)-Interview"},{"method":"test","label":"SC-30(04)-Test"}],"is_enhancement":true,"parent_id":"SC-30"},{"id":"SC-30(5)","oscal_id":"sc-30.5","family":"SC","title":"Concealment of System Components","statement":"Employ the following techniques to hide or conceal <system components>: <techniques>.","supplemental_guidance":"By hiding, disguising, or concealing critical system components, organizations may be able to decrease the probability that adversaries target and successfully compromise those assets. Potential means to hide, disguise, or conceal system components include the configuration of routers or the use of encryption or virtualization techniques.","implementation_level":"organization","parameters":[{"id":"sc-30.05_odp.01","label":"techniques"},{"id":"sc-30.05_odp.02","label":"system components"}],"methods":[{"method":"examine","label":"SC-30(05)-Examine"},{"method":"interview","label":"SC-30(05)-Interview"},{"method":"test","label":"SC-30(05)-Test"}],"is_enhancement":true,"parent_id":"SC-30"}]},{"id":"SC-31","oscal_id":"sc-31","family":"SC","title":"Covert Channel Analysis","statement":"a. Perform a covert channel analysis to identify those aspects of communications within the system that are potential avenues for covert <organization-defined parameter> channels; and\nb. Estimate the maximum bandwidth of those channels.","supplemental_guidance":"Developers are in the best position to identify potential areas within systems that might lead to covert channels. Covert channel analysis is a meaningful activity when there is the potential for unauthorized information flows across security domains, such as in the case of systems that contain export-controlled information and have connections to external networks (i.e., networks that are not controlled by organizations). Covert channel analysis is also useful for multilevel secure systems, multiple security level systems, and cross-domain systems.","implementation_level":"organization","parameters":[{"id":"sc-31_odp","label":"","choices":["storage","timing"],"how_many":"one-or-more"}],"objectives":[{"id":"sc-31_obj.a","label":"SC-31a.","text":"a covert channel analysis is performed to identify those aspects of communications within the system that are potential avenues for covert {{ insert: param, sc-31_odp }} channels;"},{"id":"sc-31_obj.b","label":"SC-31b.","text":"the maximum bandwidth of those channels is estimated."}],"methods":[{"method":"examine","label":"SC-31-Examine"},{"method":"interview","label":"SC-31-Interview"},{"method":"test","label":"SC-31-Test"}],"related_controls":["AC-3","AC-4","SA-8","SI-11"],"enhancements":[{"id":"SC-31(1)","oscal_id":"sc-31.1","family":"SC","title":"Test Covert Channels for Exploitability","statement":"Test a subset of the identified covert channels to determine the channels that are exploitable.","supplemental_guidance":"None.","implementation_level":"organization","methods":[{"method":"examine","label":"SC-31(01)-Examine"},{"method":"interview","label":"SC-31(01)-Interview"},{"method":"test","label":"SC-31(01)-Test"}],"is_enhancement":true,"parent_id":"SC-31"},{"id":"SC-31(2)","oscal_id":"sc-31.2","family":"SC","title":"Maximum Bandwidth","statement":"Reduce the maximum bandwidth for identified covert <organization-defined parameter> channels to <values>.","supplemental_guidance":"The complete elimination of covert channels, especially covert timing channels, is usually not possible without significant performance impacts.","implementation_level":"organization","parameters":[{"id":"sc-31.02_odp.01","label":"","choices":["storage","timing"],"how_many":"one-or-more"},{"id":"sc-31.02_odp.02","label":"values"}],"methods":[{"method":"examine","label":"SC-31(02)-Examine"},{"method":"interview","label":"SC-31(02)-Interview"},{"method":"test","label":"SC-31(02)-Test"}],"is_enhancement":true,"parent_id":"SC-31"},{"id":"SC-31(3)","oscal_id":"sc-31.3","family":"SC","title":"Measure Bandwidth in Operational Environments","statement":"Measure the bandwidth of <subset of identified covert channels> in the operational environment of the system.","supplemental_guidance":"Measuring covert channel bandwidth in specified operational environments helps organizations determine how much information can be covertly leaked before such leakage adversely affects mission or business functions. Covert channel bandwidth may be significantly different when measured in settings that are independent of the specific environments of operation, including laboratories or system development environments.","implementation_level":"organization","parameters":[{"id":"sc-31.03_odp","label":"subset of identified covert channels"}],"methods":[{"method":"examine","label":"SC-31(03)-Examine"},{"method":"interview","label":"SC-31(03)-Interview"},{"method":"test","label":"SC-31(03)-Test"}],"is_enhancement":true,"parent_id":"SC-31"}]},{"id":"SC-32","oscal_id":"sc-32","family":"SC","title":"System Partitioning","statement":"Partition the system into <system components> residing in separate <organization-defined parameter> domains or environments based on <circumstances for the physical or logical separation of components>.","supplemental_guidance":"System partitioning is part of a defense-in-depth protection strategy. Organizations determine the degree of physical separation of system components. Physical separation options include physically distinct components in separate racks in the same room, critical components in separate rooms, and geographical separation of critical components. Security categorization can guide the selection of candidates for domain partitioning. Managed interfaces restrict or prohibit network access and information flow among partitioned system components.","implementation_level":"organization","parameters":[{"id":"sc-32_odp.01","label":"system components"},{"id":"sc-32_odp.02","label":"","choices":["physical","logical"]},{"id":"sc-32_odp.03","label":"circumstances for the physical or logical separation of components"}],"methods":[{"method":"examine","label":"SC-32-Examine"},{"method":"interview","label":"SC-32-Interview"},{"method":"test","label":"SC-32-Test"}],"references":[{"title":"FIPS 199"},{"title":"IR 8179"}],"related_controls":["AC-4","AC-6","SA-8","SC-2","SC-3","SC-7","SC-36"],"enhancements":[{"id":"SC-32(1)","oscal_id":"sc-32.1","family":"SC","title":"Separate Physical Domains for Privileged Functions","statement":"Partition privileged functions into separate physical domains.","supplemental_guidance":"Privileged functions that operate in a single physical domain may represent a single point of failure if that domain becomes compromised or experiences a denial of service.","implementation_level":"organization","methods":[{"method":"examine","label":"SC-32-Examine"},{"method":"interview","label":"SC-32-Interview"},{"method":"test","label":"SC-32-Test"}],"is_enhancement":true,"parent_id":"SC-32"}]},{"id":"SC-33","oscal_id":"sc-33","family":"SC","title":"Transmission Preparation Integrity","statement":""},{"id":"SC-34","oscal_id":"sc-34","family":"SC","title":"Non-modifiable Executable Programs","statement":"For <system components> , load and execute:\na. The operating environment from hardware-enforced, read-only media; and\nb. The following applications from hardware-enforced, read-only media: <applications>.","supplemental_guidance":"The operating environment for a system contains the code that hosts applications, including operating systems, executives, or virtual machine monitors (i.e., hypervisors). It can also include certain applications that run directly on hardware platforms. Hardware-enforced, read-only media include Compact Disc-Recordable (CD-R) and Digital Versatile Disc-Recordable (DVD-R) disk drives as well as one-time, programmable, read-only memory. The use of non-modifiable storage ensures the integrity of software from the point of creation of the read-only image. The use of reprogrammable, read-only memory can be accepted as read-only media provided that integrity can be adequately protected from the point of initial writing to the insertion of the memory into the system, and there are reliable hardware protections against reprogramming the memory while installed in organizational systems.","implementation_level":"system","parameters":[{"id":"sc-34_odp.01","label":"system components"},{"id":"sc-34_odp.02","label":"applications"}],"objectives":[{"id":"sc-34_obj.a","label":"SC-34a.","text":"the operating environment for {{ insert: param, sc-34_odp.01 }} is loaded and executed from hardware-enforced, read-only media;"},{"id":"sc-34_obj.b","label":"SC-34b.","text":"{{ insert: param, sc-34_odp.02 }} for {{ insert: param, sc-34_odp.01 }} are loaded and executed from hardware-enforced, read-only media."}],"methods":[{"method":"examine","label":"SC-34-Examine"},{"method":"interview","label":"SC-34-Interview"},{"method":"test","label":"SC-34-Test"}],"related_controls":["AC-3","SI-7","SI-14"],"enhancements":[{"id":"SC-34(1)","oscal_id":"sc-34.1","family":"SC","title":"No Writable Storage","statement":"Employ <system components> with no writeable storage that is persistent across component restart or power on/off.","supplemental_guidance":"Disallowing writeable storage eliminates the possibility of malicious code insertion via persistent, writeable storage within the designated system components. The restriction applies to fixed and removable storage, with the latter being addressed either directly or as specific restrictions imposed through access controls for mobile devices.","implementation_level":"organization","parameters":[{"id":"sc-34.01_odp","label":"system components"}],"methods":[{"method":"examine","label":"SC-34(01)-Examine"},{"method":"interview","label":"SC-34(01)-Interview"},{"method":"test","label":"SC-34(01)-Test"}],"related_controls":["AC-19","MP-7"],"is_enhancement":true,"parent_id":"SC-34"},{"id":"SC-34(2)","oscal_id":"sc-34.2","family":"SC","title":"Integrity Protection on Read-only Media","statement":"Protect the integrity of information prior to storage on read-only media and control the media after such information has been recorded onto the media.","supplemental_guidance":"Controls prevent the substitution of media into systems or the reprogramming of programmable read-only media prior to installation into the systems. Integrity protection controls include a combination of prevention, detection, and response.","implementation_level":"organization","objectives":[{"id":"sc-34.2_obj-1","label":"SC-34(02)[01]","text":"the integrity of information is protected prior to storage on read-only media;"},{"id":"sc-34.2_obj-2","label":"SC-34(02)[02]","text":"the media is controlled after such information has been recorded onto the media;"}],"methods":[{"method":"examine","label":"SC-34(02)-Examine"},{"method":"interview","label":"SC-34(02)-Interview"},{"method":"test","label":"SC-34(02)-Test"}],"related_controls":["CM-3","CM-5","CM-9","MP-2","MP-4","MP-5","SC-28","SI-3"],"is_enhancement":true,"parent_id":"SC-34"},{"id":"SC-34(3)","oscal_id":"sc-34.3","family":"SC","title":"Hardware-based Protection","statement":"","is_enhancement":true,"parent_id":"SC-34"}]},{"id":"SC-35","oscal_id":"sc-35","family":"SC","title":"External Malicious Code Identification","statement":"Include system components that proactively seek to identify network-based malicious code or malicious websites.","supplemental_guidance":"External malicious code identification differs from decoys in [SC-26](#sc-26) in that the components actively probe networks, including the Internet, in search of malicious code contained on external websites. Like decoys, the use of external malicious code identification techniques requires some supporting isolation measures to ensure that any malicious code discovered during the search and subsequently executed does not infect organizational systems. Virtualization is a common technique for achieving such isolation.","implementation_level":"system","methods":[{"method":"examine","label":"SC-35-Examine"},{"method":"interview","label":"SC-35-Interview"},{"method":"test","label":"SC-35-Test"}],"related_controls":["SC-7","SC-26","SC-44","SI-3","SI-4"]},{"id":"SC-36","oscal_id":"sc-36","family":"SC","title":"Distributed Processing and Storage","statement":"Distribute the following processing and storage components across multiple <organization-defined parameter>: <organization-defined processing and storage components>.","supplemental_guidance":"Distributing processing and storage across multiple physical locations or logical domains provides a degree of redundancy or overlap for organizations. The redundancy and overlap increase the work factor of adversaries to adversely impact organizational operations, assets, and individuals. The use of distributed processing and storage does not assume a single primary processing or storage location. Therefore, it allows for parallel processing and storage.","implementation_level":"organization","parameters":[{"id":"sc-36_prm_1","label":"","choices":["physical locations","logical domains"]},{"id":"sc-36_prm_2","label":"organization-defined processing and storage components"},{"id":"sc-36_odp.01","label":"processing components"},{"id":"sc-36_odp.02","label":"","choices":["physical locations","logical domains"]},{"id":"sc-36_odp.03","label":"storage components"},{"id":"sc-36_odp.04","label":"","choices":["physical locations","logical domains"]}],"objectives":[{"id":"sc-36_obj-1","label":"SC-36[01]","text":"{{ insert: param, sc-36_odp.01 }} are distributed across {{ insert: param, sc-36_odp.02 }};"},{"id":"sc-36_obj-2","label":"SC-36[02]","text":"{{ insert: param, sc-36_odp.03 }} are distributed across {{ insert: param, sc-36_odp.04 }}."}],"methods":[{"method":"examine","label":"SC-36-Examine"},{"method":"interview","label":"SC-36-Interview"},{"method":"test","label":"SC-36-Test"}],"references":[{"title":"SP 800-160-2"}],"related_controls":["CP-6","CP-7","PL-8","SC-32"],"enhancements":[{"id":"SC-36(1)","oscal_id":"sc-36.1","family":"SC","title":"Polling Techniques","statement":"(a) Employ polling techniques to identify potential faults, errors, or compromises to the following processing and storage components: <distributed processing and storage components> ; and\n(b) Take the following actions in response to identified faults, errors, or compromises: <actions>.","supplemental_guidance":"Distributed processing and/or storage may be used to reduce opportunities for adversaries to compromise the confidentiality, integrity, or availability of organizational information and systems. However, the distribution of processing and storage components does not prevent adversaries from compromising one or more of the components. Polling compares the processing results and/or storage content from the distributed components and subsequently votes on the outcomes. Polling identifies potential faults, compromises, or errors in the distributed processing and storage components.","implementation_level":"organization","parameters":[{"id":"sc-36.01_odp.01","label":"distributed processing and storage components"},{"id":"sc-36.01_odp.02","label":"actions"}],"objectives":[{"id":"sc-36.1_obj.a","label":"SC-36(01)(a)","text":"polling techniques are employed to identify potential faults, errors, or compromises to {{ insert: param, sc-36.01_odp.01 }};"},{"id":"sc-36.1_obj.b","label":"SC-36(01)(b)","text":"{{ insert: param, sc-36.01_odp.02 }} are taken in response to identified faults, errors, or compromise."}],"methods":[{"method":"examine","label":"SC-36(01)-Examine"},{"method":"interview","label":"SC-36(01)-Interview"},{"method":"test","label":"SC-36(01)-Test"}],"related_controls":["SI-4"],"is_enhancement":true,"parent_id":"SC-36"},{"id":"SC-36(2)","oscal_id":"sc-36.2","family":"SC","title":"Synchronization","statement":"Synchronize the following duplicate systems or system components: <duplicate systems or system components>.","supplemental_guidance":"[SC-36](#sc-36) and [CP-9(6)](#cp-9.6) require the duplication of systems or system components in distributed locations. The synchronization of duplicated and redundant services and data helps to ensure that information contained in the distributed locations can be used in the mission or business functions of organizations, as needed.","implementation_level":"organization","parameters":[{"id":"sc-36.02_odp","label":"duplicate systems or system components"}],"methods":[{"method":"examine","label":"SC-36(02)-Examine"},{"method":"interview","label":"SC-36(02)-Interview"},{"method":"test","label":"SC-36(02)-Test"}],"related_controls":["CP-9"],"is_enhancement":true,"parent_id":"SC-36"}]},{"id":"SC-37","oscal_id":"sc-37","family":"SC","title":"Out-of-band Channels","statement":"Employ the following out-of-band channels for the physical delivery or electronic transmission of <information, system components, or devices> to <individuals or systems>: <out-of-band channels>.","supplemental_guidance":"Out-of-band channels include local, non-network accesses to systems; network paths physically separate from network paths used for operational traffic; or non-electronic paths, such as the U.S. Postal Service. The use of out-of-band channels is contrasted with the use of in-band channels (i.e., the same channels) that carry routine operational traffic. Out-of-band channels do not have the same vulnerability or exposure as in-band channels. Therefore, the confidentiality, integrity, or availability compromises of in-band channels will not compromise or adversely affect the out-of-band channels. Organizations may employ out-of-band channels in the delivery or transmission of organizational items, including authenticators and credentials; cryptographic key management information; system and data backups; configuration management changes for hardware, firmware, or software; security updates; maintenance information; and malicious code protection updates. For example, cryptographic keys for encrypted files are delivered using a different channel than the file.","implementation_level":"organization","parameters":[{"id":"sc-37_odp.01","label":"out-of-band channels"},{"id":"sc-37_odp.02","label":"information, system components, or devices"},{"id":"sc-37_odp.03","label":"individuals or systems"}],"methods":[{"method":"examine","label":"SC-37-Examine"},{"method":"interview","label":"SC-37-Interview"},{"method":"test","label":"SC-37-Test"}],"references":[{"title":"SP 800-57-1"},{"title":"SP 800-57-2"},{"title":"SP 800-57-3"}],"related_controls":["AC-2","CM-3","CM-5","CM-7","IA-2","IA-4","IA-5","MA-4","SC-12","SI-3","SI-4","SI-7"],"enhancements":[{"id":"SC-37(1)","oscal_id":"sc-37.1","family":"SC","title":"Ensure Delivery and Transmission","statement":"Employ <controls> to ensure that only <individuals or systems> receive the following information, system components, or devices: <information, system components, or devices>.","supplemental_guidance":"Techniques employed by organizations to ensure that only designated systems or individuals receive certain information, system components, or devices include sending authenticators via an approved courier service but requiring recipients to show some form of government-issued photographic identification as a condition of receipt.","implementation_level":"organization","parameters":[{"id":"sc-37.01_odp.01","label":"controls"},{"id":"sc-37.01_odp.02","label":"individuals or systems"},{"id":"sc-37.01_odp.03","label":"information, system components, or devices"}],"methods":[{"method":"examine","label":"SC-37(01)-Examine"},{"method":"interview","label":"SC-37(01)-Interview"},{"method":"test","label":"SC-37(01)-Test"}],"is_enhancement":true,"parent_id":"SC-37"}]},{"id":"SC-38","oscal_id":"sc-38","family":"SC","title":"Operations Security","statement":"Employ the following operations security controls to protect key organizational information throughout the system development life cycle: <operations security controls>.","supplemental_guidance":"Operations security (OPSEC) is a systematic process by which potential adversaries can be denied information about the capabilities and intentions of organizations by identifying, controlling, and protecting generally unclassified information that specifically relates to the planning and execution of sensitive organizational activities. The OPSEC process involves five steps: identification of critical information, analysis of threats, analysis of vulnerabilities, assessment of risks, and the application of appropriate countermeasures. OPSEC controls are applied to organizational systems and the environments in which those systems operate. OPSEC controls protect the confidentiality of information, including limiting the sharing of information with suppliers, potential suppliers, and other non-organizational elements and individuals. Information critical to organizational mission and business functions includes user identities, element uses, suppliers, supply chain processes, functional requirements, security requirements, system design specifications, testing and evaluation protocols, and security control implementation details.","implementation_level":"organization","parameters":[{"id":"sc-38_odp","label":"operations security controls"}],"methods":[{"method":"examine","label":"SC-38-Examine"},{"method":"interview","label":"SC-38-Interview"},{"method":"test","label":"SC-38-Test"}],"related_controls":["CA-2","CA-7","PL-1","PM-9","PM-12","RA-2","RA-3","RA-5","SC-7","SR-3","SR-7"]},{"id":"SC-39","oscal_id":"sc-39","family":"SC","title":"Process Isolation","statement":"Maintain a separate execution domain for each executing system process.","supplemental_guidance":"Systems can maintain separate execution domains for each executing process by assigning each process a separate address space. Each system process has a distinct address space so that communication between processes is performed in a manner controlled through the security functions, and one process cannot modify the executing code of another process. Maintaining separate execution domains for executing processes can be achieved, for example, by implementing separate address spaces. Process isolation technologies, including sandboxing or virtualization, logically separate software and firmware from other software, firmware, and data. Process isolation helps limit the access of potentially untrusted software to other system resources. The capability to maintain separate execution domains is available in commercial operating systems that employ multi-state processor technologies.","implementation_level":"system","methods":[{"method":"examine","label":"SC-39-Examine"},{"method":"interview","label":"SC-39-Interview"},{"method":"test","label":"SC-39-Test"}],"references":[{"title":"SP 800-160-1"}],"related_controls":["AC-3","AC-4","AC-6","AC-25","SA-8","SC-2","SC-3","SI-16"],"enhancements":[{"id":"SC-39(1)","oscal_id":"sc-39.1","family":"SC","title":"Hardware Separation","statement":"Implement hardware separation mechanisms to facilitate process isolation.","supplemental_guidance":"Hardware-based separation of system processes is generally less susceptible to compromise than software-based separation, thus providing greater assurance that the separation will be enforced. Hardware separation mechanisms include hardware memory management.","implementation_level":"system","methods":[{"method":"examine","label":"SC-39(01)-Examine"},{"method":"interview","label":"SC-39(01)-Interview"},{"method":"test","label":"SC-39(01)-Test"}],"is_enhancement":true,"parent_id":"SC-39"},{"id":"SC-39(2)","oscal_id":"sc-39.2","family":"SC","title":"Separate Execution Domain Per Thread","statement":"Maintain a separate execution domain for each thread in <multi-threaded processing>.","supplemental_guidance":"None.","implementation_level":"system","parameters":[{"id":"sc-39.02_odp","label":"multi-threaded processing"}],"methods":[{"method":"examine","label":"SC-39(02)-Examine"},{"method":"interview","label":"SC-39(02)-Interview"},{"method":"test","label":"SC-39(02)-Test"}],"is_enhancement":true,"parent_id":"SC-39"}]},{"id":"SC-40","oscal_id":"sc-40","family":"SC","title":"Wireless Link Protection","statement":"Protect external and internal <organization-defined wireless links> from the following signal parameter attacks: <organization-defined types of signal parameter attacks or references to sources for such attacks>.","supplemental_guidance":"Wireless link protection applies to internal and external wireless communication links that may be visible to individuals who are not authorized system users. Adversaries can exploit the signal parameters of wireless links if such links are not adequately protected. There are many ways to exploit the signal parameters of wireless links to gain intelligence, deny service, or spoof system users. Protection of wireless links reduces the impact of attacks that are unique to wireless systems. If organizations rely on commercial service providers for transmission services as commodity items rather than as fully dedicated services, it may not be possible to implement wireless link protections to the extent necessary to meet organizational security requirements.","implementation_level":"system","parameters":[{"id":"sc-40_prm_1","label":"organization-defined wireless links"},{"id":"sc-40_prm_2","label":"organization-defined types of signal parameter attacks or references to sources for such attacks"},{"id":"sc-40_odp.01","label":"wireless links"},{"id":"sc-40_odp.02","label":"types of signal parameter attacks or references to sources for such attacks"},{"id":"sc-40_odp.03","label":"wireless links"},{"id":"sc-40_odp.04","label":"types of signal parameter attacks or references to sources for such attacks"}],"objectives":[{"id":"sc-40_obj-1","label":"SC-40[01]","text":"external {{ insert: param, sc-40_odp.01 }} are protected from {{ insert: param, sc-40_odp.02 }}."},{"id":"sc-40_obj-2","label":"SC-40[02]","text":"internal {{ insert: param, sc-40_odp.03 }} are protected from {{ insert: param, sc-40_odp.04 }}."}],"methods":[{"method":"examine","label":"SC-40-Examine"},{"method":"interview","label":"SC-40-Interview"},{"method":"test","label":"SC-40-Test"}],"related_controls":["AC-18","SC-5"],"enhancements":[{"id":"SC-40(1)","oscal_id":"sc-40.1","family":"SC","title":"Electromagnetic Interference","statement":"Implement cryptographic mechanisms that achieve <level of protection> against the effects of intentional electromagnetic interference.","supplemental_guidance":"The implementation of cryptographic mechanisms for electromagnetic interference protects systems against intentional jamming that might deny or impair communications by ensuring that wireless spread spectrum waveforms used to provide anti-jam protection are not predictable by unauthorized individuals. The implementation of cryptographic mechanisms may also coincidentally mitigate the effects of unintentional jamming due to interference from legitimate transmitters that share the same spectrum. Mission requirements, projected threats, concept of operations, and laws, executive orders, directives, regulations, policies, and standards determine levels of wireless link availability, cryptography needed, and performance.","implementation_level":"system","parameters":[{"id":"sc-40.01_odp","label":"level of protection"}],"methods":[{"method":"examine","label":"SC-40(01)-Examine"},{"method":"interview","label":"SC-40(01)-Interview"},{"method":"test","label":"SC-40(01)-Test"}],"related_controls":["PE-21","SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-40"},{"id":"SC-40(2)","oscal_id":"sc-40.2","family":"SC","title":"Reduce Detection Potential","statement":"Implement cryptographic mechanisms to reduce the detection potential of wireless links to <level of reduction>.","supplemental_guidance":"The implementation of cryptographic mechanisms to reduce detection potential is used for covert communications and to protect wireless transmitters from geo-location. It also ensures that the spread spectrum waveforms used to achieve a low probability of detection are not predictable by unauthorized individuals. Mission requirements, projected threats, concept of operations, and applicable laws, executive orders, directives, regulations, policies, and standards determine the levels to which wireless links are undetectable.","implementation_level":"system","parameters":[{"id":"sc-40.02_odp","label":"level of reduction"}],"methods":[{"method":"examine","label":"SC-40(02)-Examine"},{"method":"interview","label":"SC-40(02)-Interview"},{"method":"test","label":"SC-40(02)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-40"},{"id":"SC-40(3)","oscal_id":"sc-40.3","family":"SC","title":"Imitative or Manipulative Communications Deception","statement":"Implement cryptographic mechanisms to identify and reject wireless transmissions that are deliberate attempts to achieve imitative or manipulative communications deception based on signal parameters.","supplemental_guidance":"The implementation of cryptographic mechanisms to identify and reject imitative or manipulative communications ensures that the signal parameters of wireless transmissions are not predictable by unauthorized individuals. Such unpredictability reduces the probability of imitative or manipulative communications deception based on signal parameters alone.","implementation_level":"system","methods":[{"method":"examine","label":"SC-40(03)-Examine"},{"method":"interview","label":"SC-40(03)-Interview"},{"method":"test","label":"SC-40(03)-Test"}],"related_controls":["SC-12","SC-13","SI-4"],"is_enhancement":true,"parent_id":"SC-40"},{"id":"SC-40(4)","oscal_id":"sc-40.4","family":"SC","title":"Signal Parameter Identification","statement":"Implement cryptographic mechanisms to prevent the identification of <wireless transmitters> by using the transmitter signal parameters.","supplemental_guidance":"The implementation of cryptographic mechanisms to prevent the identification of wireless transmitters protects against the unique identification of wireless transmitters for the purposes of intelligence exploitation by ensuring that anti-fingerprinting alterations to signal parameters are not predictable by unauthorized individuals. It also provides anonymity when required. Radio fingerprinting techniques identify the unique signal parameters of transmitters to fingerprint such transmitters for purposes of tracking and mission or user identification.","implementation_level":"system","parameters":[{"id":"sc-40.04_odp","label":"wireless transmitters"}],"methods":[{"method":"examine","label":"SC-40(04)-Examine"},{"method":"interview","label":"SC-40(04)-Interview"},{"method":"test","label":"SC-40(04)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"SC-40"}]},{"id":"SC-41","oscal_id":"sc-41","family":"SC","title":"Port and I/O Device Access","statement":"<organization-defined parameter> disable or remove <connection ports or input/output devices> on the following systems or system components: <systems or system components>.","supplemental_guidance":"Connection ports include Universal Serial Bus (USB), Thunderbolt, and Firewire (IEEE 1394). Input/output (I/O) devices include compact disc and digital versatile disc drives. Disabling or removing such connection ports and I/O devices helps prevent the exfiltration of information from systems and the introduction of malicious code from those ports or devices. Physically disabling or removing ports and/or devices is the stronger action.","implementation_level":"organization","parameters":[{"id":"sc-41_odp.01","label":"connection ports or input/output devices"},{"id":"sc-41_odp.02","label":"","choices":["physically","logically"]},{"id":"sc-41_odp.03","label":"systems or system components"}],"methods":[{"method":"examine","label":"SC-41-Examine"},{"method":"interview","label":"SC-41-Interview"},{"method":"test","label":"SC-41-Test"}],"related_controls":["AC-20","MP-7"]},{"id":"SC-42","oscal_id":"sc-42","family":"SC","title":"Sensor Capability and Data","statement":"a. Prohibit <organization-defined parameter> ; and\nb. Provide an explicit indication of sensor use to <group of users>.","supplemental_guidance":"Sensor capability and data applies to types of systems or system components characterized as mobile devices, such as cellular telephones, smart phones, and tablets. Mobile devices often include sensors that can collect and record data regarding the environment where the system is in use. Sensors that are embedded within mobile devices include microphones, cameras, Global Positioning System (GPS) mechanisms, and accelerometers. While the sensors on mobiles devices provide an important function, if activated covertly, such devices can potentially provide a means for adversaries to learn valuable information about individuals and organizations. For example, remotely activating the GPS function on a mobile device could provide an adversary with the ability to track the movements of an individual. Organizations may prohibit individuals from bringing cellular telephones or digital cameras into certain designated facilities or controlled areas within facilities where classified information is stored or sensitive conversations are taking place.","implementation_level":"system","parameters":[{"id":"sc-42_odp.01","label":"","choices":["the use of devices possessing {{ insert: param, sc-42_odp.02 }} in {{ insert: param, sc-42_odp.03 }} ","the remote activation of environmental sensing capabilities on organizational systems or system components with the following exceptions: {{ insert: param, sc-42_odp.04 }} "],"how_many":"one-or-more"},{"id":"sc-42_odp.02","label":"environmental sensing capabilities"},{"id":"sc-42_odp.03","label":"facilities, areas, or systems"},{"id":"sc-42_odp.04","label":"exceptions where remote activation of sensors is allowed"},{"id":"sc-42_odp.05","label":"group of users"}],"objectives":[{"id":"sc-42_obj.a","label":"SC-42a.","text":"{{ insert: param, sc-42_odp.01 }} is/are prohibited;"},{"id":"sc-42_obj.b","label":"SC-42b.","text":"an explicit indication of sensor use is provided to {{ insert: param, sc-42_odp.05 }}."}],"methods":[{"method":"examine","label":"SC-42-Examine"},{"method":"interview","label":"SC-42-Interview"},{"method":"test","label":"SC-42-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-124"}],"related_controls":["SC-15"],"enhancements":[{"id":"SC-42(1)","oscal_id":"sc-42.1","family":"SC","title":"Reporting to Authorized Individuals or Roles","statement":"Verify that the system is configured so that data or information collected by the <sensors> is only reported to authorized individuals or roles.","supplemental_guidance":"In situations where sensors are activated by authorized individuals, it is still possible that the data or information collected by the sensors will be sent to unauthorized entities.","implementation_level":"organization","parameters":[{"id":"sc-42.01_odp","label":"sensors"}],"methods":[{"method":"examine","label":"SC-42(01)-Examine"},{"method":"interview","label":"SC-42(01)-Interview"},{"method":"test","label":"SC-42(01)-Test"}],"is_enhancement":true,"parent_id":"SC-42"},{"id":"SC-42(2)","oscal_id":"sc-42.2","family":"SC","title":"Authorized Use","statement":"Employ the following measures so that data or information collected by <organization-defined parameter> is only used for authorized purposes: <measures>.","supplemental_guidance":"Information collected by sensors for a specific authorized purpose could be misused for some unauthorized purpose. For example, GPS sensors that are used to support traffic navigation could be misused to track the movements of individuals. Measures to mitigate such activities include additional training to help ensure that authorized individuals do not abuse their authority and, in the case where sensor data is maintained by external parties, contractual restrictions on the use of such data.","implementation_level":"organization","parameters":[{"id":"sc-42.02_odp","label":"measures"}],"methods":[{"method":"examine","label":"SC-42(02)-Examine"},{"method":"interview","label":"SC-42(02)-Interview"},{"method":"test","label":"SC-42(02)-Test"}],"related_controls":["PT-2"],"is_enhancement":true,"parent_id":"SC-42"},{"id":"SC-42(3)","oscal_id":"sc-42.3","family":"SC","title":"Prohibit Use of Devices","statement":"","is_enhancement":true,"parent_id":"SC-42"},{"id":"SC-42(4)","oscal_id":"sc-42.4","family":"SC","title":"Notice of Collection","statement":"Employ the following measures to facilitate an individual’s awareness that personally identifiable information is being collected by <sensors>: <measures>.","supplemental_guidance":"Awareness that organizational sensors are collecting data enables individuals to more effectively engage in managing their privacy. Measures can include conventional written notices and sensor configurations that make individuals directly or indirectly aware through other devices that the sensor is collecting information. The usability and efficacy of the notice are important considerations.","implementation_level":"organization","parameters":[{"id":"sc-42.04_odp.01","label":"measures"},{"id":"sc-42.04_odp.02","label":"sensors"}],"methods":[{"method":"examine","label":"SC-42(04)-Examine"},{"method":"interview","label":"SC-42(04)-Interview"},{"method":"test","label":"SC-42(04)-Test"}],"related_controls":["PT-1","PT-4","PT-5"],"is_enhancement":true,"parent_id":"SC-42"},{"id":"SC-42(5)","oscal_id":"sc-42.5","family":"SC","title":"Collection Minimization","statement":"Employ <sensors> that are configured to minimize the collection of information about individuals that is not needed.","supplemental_guidance":"Although policies to control for authorized use can be applied to information once it is collected, minimizing the collection of information that is not needed mitigates privacy risk at the system entry point and mitigates the risk of policy control failures. Sensor configurations include the obscuring of human features, such as blurring or pixelating flesh tones.","implementation_level":"organization","parameters":[{"id":"sc-42.05_odp","label":"sensors"}],"methods":[{"method":"examine","label":"SC-42(05)-Examine"},{"method":"interview","label":"SC-42(05)-Interview"},{"method":"test","label":"SC-42(05)-Test"}],"related_controls":["SA-8","SI-12"],"is_enhancement":true,"parent_id":"SC-42"}]},{"id":"SC-43","oscal_id":"sc-43","family":"SC","title":"Usage Restrictions","statement":"a. Establish usage restrictions and implementation guidelines for the following system components: <components> ; and\nb. Authorize, monitor, and control the use of such components within the system.","supplemental_guidance":"Usage restrictions apply to all system components including but not limited to mobile code, mobile devices, wireless access, and wired and wireless peripheral components (e.g., copiers, printers, scanners, optical devices, and other similar technologies). The usage restrictions and implementation guidelines are based on the potential for system components to cause damage to the system and help to ensure that only authorized system use occurs.","implementation_level":"organization","parameters":[{"id":"sc-43_odp","label":"components"}],"objectives":[{"id":"sc-43_obj.a","label":"SC-43a.","text":"usage restrictions and implementation guidelines are established for {{ insert: param, sc-43_odp }};"},{"id":"sc-43_obj.b-1","label":"SC-43b.[01]","text":"the use of {{ insert: param, sc-43_odp }} is authorized within the system;"},{"id":"sc-43_obj.b-2","label":"SC-43b.[02]","text":"the use of {{ insert: param, sc-43_odp }} is monitored within the system;"},{"id":"sc-43_obj.b-3","label":"SC-43b.[03]","text":"the use of {{ insert: param, sc-43_odp }} is controlled within the system."}],"methods":[{"method":"examine","label":"SC-43-Examine"},{"method":"interview","label":"SC-43-Interview"},{"method":"test","label":"SC-43-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-124"}],"related_controls":["AC-18","AC-19","CM-6","SC-7","SC-18"]},{"id":"SC-44","oscal_id":"sc-44","family":"SC","title":"Detonation Chambers","statement":"Employ a detonation chamber capability within <system, system component, or location>.","supplemental_guidance":"Detonation chambers, also known as dynamic execution environments, allow organizations to open email attachments, execute untrusted or suspicious applications, and execute Universal Resource Locator requests in the safety of an isolated environment or a virtualized sandbox. Protected and isolated execution environments provide a means of determining whether the associated attachments or applications contain malicious code. While related to the concept of deception nets, the employment of detonation chambers is not intended to maintain a long-term environment in which adversaries can operate and their actions can be observed. Rather, detonation chambers are intended to quickly identify malicious code and either reduce the likelihood that the code is propagated to user environments of operation or prevent such propagation completely.","implementation_level":"system","parameters":[{"id":"sc-44_odp","label":"system, system component, or location"}],"methods":[{"method":"examine","label":"SC-44-Examine"},{"method":"interview","label":"SC-44-Interview"},{"method":"test","label":"SC-44-Test"}],"references":[{"title":"SP 800-177"}],"related_controls":["SC-7","SC-18","SC-25","SC-26","SC-30","SC-35","SC-39","SI-3","SI-7"]},{"id":"SC-45","oscal_id":"sc-45","family":"SC","title":"System Time Synchronization","statement":"Synchronize system clocks within and between systems and system components.","supplemental_guidance":"Time synchronization of system clocks is essential for the correct execution of many system services, including identification and authentication processes that involve certificates and time-of-day restrictions as part of access control. Denial of service or failure to deny expired credentials may result without properly synchronized clocks within and between systems and system components. Time is commonly expressed in Coordinated Universal Time (UTC), a modern continuation of Greenwich Mean Time (GMT), or local time with an offset from UTC. The granularity of time measurements refers to the degree of synchronization between system clocks and reference clocks, such as clocks synchronizing within hundreds of milliseconds or tens of milliseconds. Organizations may define different time granularities for system components. Time service can be critical to other security capabilities—such as access control and identification and authentication—depending on the nature of the mechanisms used to support the capabilities.","implementation_level":"system","methods":[{"method":"examine","label":"SC-45-Examine"},{"method":"interview","label":"SC-45-Interview"},{"method":"test","label":"SC-45-Test"}],"references":[{"title":"IETF 5905"}],"related_controls":["AC-3","AU-8","IA-2","IA-8"],"enhancements":[{"id":"SC-45(1)","oscal_id":"sc-45.1","family":"SC","title":"Synchronization with Authoritative Time Source","statement":"(a) Compare the internal system clocks <frequency> with <authoritative time source> ; and\n(b) Synchronize the internal system clocks to the authoritative time source when the time difference is greater than <time period>.","supplemental_guidance":"Synchronization of internal system clocks with an authoritative source provides uniformity of time stamps for systems with multiple system clocks and systems connected over a network.","implementation_level":"system","parameters":[{"id":"sc-45.01_odp.01","label":"frequency"},{"id":"sc-45.01_odp.02","label":"authoritative time source"},{"id":"sc-45.01_odp.03","label":"time period"}],"objectives":[{"id":"sc-45.1_obj.a","label":"SC-45(01)(a)","text":"the internal system clocks are compared {{ insert: param, sc-45.01_odp.01 }} with {{ insert: param, sc-45.01_odp.02 }};"},{"id":"sc-45.1_obj.b","label":"SC-45(01)(b)","text":"the internal system clocks are synchronized with the authoritative time source when the time difference is greater than {{ insert: param, sc-45.01_odp.03 }}."}],"methods":[{"method":"examine","label":"SC-45(01)-Examine"},{"method":"interview","label":"SC-45(01)-Interview"},{"method":"test","label":"SC-45(01)-Test"}],"is_enhancement":true,"parent_id":"SC-45"},{"id":"SC-45(2)","oscal_id":"sc-45.2","family":"SC","title":"Secondary Authoritative Time Source","statement":"(a) Identify a secondary authoritative time source that is in a different geographic region than the primary authoritative time source; and\n(b) Synchronize the internal system clocks to the secondary authoritative time source if the primary authoritative time source is unavailable.","supplemental_guidance":"It may be necessary to employ geolocation information to determine that the secondary authoritative time source is in a different geographic region.","implementation_level":"system","objectives":[{"id":"sc-45.2_obj.a","label":"SC-45(02)(a)","text":"a secondary authoritative time source is identified that is in a different geographic region than the primary authoritative time source;"},{"id":"sc-45.2_obj.b","label":"SC-45(02)(b)","text":"the internal system clocks are synchronized to the secondary authoritative time source if the primary authoritative time source is unavailable."}],"methods":[{"method":"examine","label":"SC-45(02)-Examine"},{"method":"interview","label":"SC-45(02)-Interview"},{"method":"test","label":"SC-45(02)-Test"}],"is_enhancement":true,"parent_id":"SC-45"}]},{"id":"SC-46","oscal_id":"sc-46","family":"SC","title":"Cross Domain Policy Enforcement","statement":"Implement a policy enforcement mechanism <organization-defined parameter> between the physical and/or network interfaces for the connecting security domains.","supplemental_guidance":"For logical policy enforcement mechanisms, organizations avoid creating a logical path between interfaces to prevent the ability to bypass the policy enforcement mechanism. For physical policy enforcement mechanisms, the robustness of physical isolation afforded by the physical implementation of policy enforcement to preclude the presence of logical covert channels penetrating the security domain may be needed. Contact [ncdsmo@nsa.gov](mailto:ncdsmo@nsa.gov) for more information.","implementation_level":"system","parameters":[{"id":"sc-46_odp","label":"","choices":["physically","logically"]}],"methods":[{"method":"examine","label":"SC-46-Examine"},{"method":"interview","label":"SC-46-Interview"},{"method":"test","label":"SC-46-Test"}],"references":[{"title":"SP 800-160-1"}],"related_controls":["AC-4","SC-7"]},{"id":"SC-47","oscal_id":"sc-47","family":"SC","title":"Alternate Communications Paths","statement":"Establish <alternate communication paths> for system operations organizational command and control.","supplemental_guidance":"An incident, whether adversarial- or nonadversarial-based, can disrupt established communications paths used for system operations and organizational command and control. Alternate communications paths reduce the risk of all communications paths being affected by the same incident. To compound the problem, the inability of organizational officials to obtain timely information about disruptions or to provide timely direction to operational elements after a communications path incident, can impact the ability of the organization to respond to such incidents in a timely manner. Establishing alternate communications paths for command and control purposes, including designating alternative decision makers if primary decision makers are unavailable and establishing the extent and limitations of their actions, can greatly facilitate the organization’s ability to continue to operate and take appropriate actions during an incident.","implementation_level":"organization","parameters":[{"id":"sc-47_odp","label":"alternate communication paths"}],"methods":[{"method":"examine","label":"SC-47-Examine"},{"method":"interview","label":"SC-47-Interview"},{"method":"test","label":"SC-47-Test"}],"references":[{"title":"SP 800-34"},{"title":"SP 800-61"},{"title":"SP 800-160-2"}],"related_controls":["CP-2","CP-8"]},{"id":"SC-48","oscal_id":"sc-48","family":"SC","title":"Sensor Relocation","statement":"Relocate <sensors and monitoring capabilities> to <locations> under the following conditions or circumstances: <conditions or circumstances>.","supplemental_guidance":"Adversaries may take various paths and use different approaches as they move laterally through an organization (including its systems) to reach their target or as they attempt to exfiltrate information from the organization. The organization often only has a limited set of monitoring and detection capabilities, and they may be focused on the critical or likely infiltration or exfiltration paths. By using communications paths that the organization typically does not monitor, the adversary can increase its chances of achieving its desired goals. By relocating its sensors or monitoring capabilities to new locations, the organization can impede the adversary’s ability to achieve its goals. The relocation of the sensors or monitoring capabilities might be done based on threat information that the organization has acquired or randomly to confuse the adversary and make its lateral transition through the system or organization more challenging.","implementation_level":"organization","parameters":[{"id":"sc-48_odp.01","label":"sensors and monitoring capabilities"},{"id":"sc-48_odp.02","label":"locations"},{"id":"sc-48_odp.03","label":"conditions or circumstances"}],"methods":[{"method":"examine","label":"SC-48-Examine"},{"method":"interview","label":"SC-48-Interview"},{"method":"test","label":"SC-48-Test"}],"references":[{"title":"SP 800-160-2"}],"related_controls":["AU-2","SC-7","SI-4"],"enhancements":[{"id":"SC-48(1)","oscal_id":"sc-48.1","family":"SC","title":"Dynamic Relocation of Sensors or Monitoring Capabilities","statement":"Dynamically relocate <sensors and monitoring capabilities> to <locations> under the following conditions or circumstances: <conditions or circumstances>.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"sc-48.01_odp.01","label":"sensors and monitoring capabilities"},{"id":"sc-48.01_odp.02","label":"locations"},{"id":"sc-48.01_odp.03","label":"conditions or circumstances"}],"methods":[{"method":"examine","label":"SC-48(01)-Examine"},{"method":"interview","label":"SC-48(01)-Interview"},{"method":"test","label":"SC-48(01)-Test"}],"is_enhancement":true,"parent_id":"SC-48"}]},{"id":"SC-49","oscal_id":"sc-49","family":"SC","title":"Hardware-enforced Separation and Policy Enforcement","statement":"Implement hardware-enforced separation and policy enforcement mechanisms between <security domains>.","supplemental_guidance":"System owners may require additional strength of mechanism and robustness to ensure domain separation and policy enforcement for specific types of threats and environments of operation. Hardware-enforced separation and policy enforcement provide greater strength of mechanism than software-enforced separation and policy enforcement.","implementation_level":"organization","parameters":[{"id":"sc-49_odp","label":"security domains"}],"methods":[{"method":"examine","label":"SC-49-Examine"},{"method":"interview","label":"SC-49-Interview"},{"method":"test","label":"SC-49-Test"}],"references":[{"title":"SP 800-160-1"}],"related_controls":["AC-4","SA-8","SC-50"]},{"id":"SC-50","oscal_id":"sc-50","family":"SC","title":"Software-enforced Separation and Policy Enforcement","statement":"Implement software-enforced separation and policy enforcement mechanisms between <security domains>.","supplemental_guidance":"System owners may require additional strength of mechanism to ensure domain separation and policy enforcement for specific types of threats and environments of operation.","implementation_level":"organization","parameters":[{"id":"sc-50_odp","label":"security domains"}],"methods":[{"method":"examine","label":"SC-50-Examine"},{"method":"interview","label":"SC-50-Interview"},{"method":"test","label":"SC-50-Test"}],"references":[{"title":"SP 800-160-1"}],"related_controls":["AC-3","AC-4","SA-8","SC-2","SC-3","SC-49"]},{"id":"SC-51","oscal_id":"sc-51","family":"SC","title":"Hardware-based Protection","statement":"a. Employ hardware-based, write-protect for <system firmware components> ; and\nb. Implement specific procedures for <authorized individuals> to manually disable hardware write-protect for firmware modifications and re-enable the write-protect prior to returning to operational mode.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"sc-51_odp.01","label":"system firmware components"},{"id":"sc-51_odp.02","label":"authorized individuals"}],"objectives":[{"id":"sc-51_obj.a","label":"SC-51a.","text":"hardware-based write-protect for {{ insert: param, sc-51_odp.01 }} is employed;"},{"id":"sc-51_obj.b-1","label":"SC-51b.[01]","text":"specific procedures are implemented for {{ insert: param, sc-51_odp.02 }} to manually disable hardware write-protect for firmware modifications;"},{"id":"sc-51_obj.b-2","label":"SC-51b.[02]","text":"specific procedures are implemented for {{ insert: param, sc-51_odp.02 }} to re-enable the write-protect prior to returning to operational mode."}],"methods":[{"method":"examine","label":"SC-51-Examine"},{"method":"interview","label":"SC-51-Interview"},{"method":"test","label":"SC-51-Test"}]}]};
